package pkgTTTBackend;

import java.util.*;

public class KDTTTBoard {
    private final static int ROWS = 3, COLS = 3;
    private static final char[][] my_list = new char[ROWS][COLS];
    private static final Scanner myScanner = new Scanner(System.in);
    public static Scanner myScanner(){
        return myScanner;
    }
    private void setMylist(int row, int col) {
        my_list[row][col] = 'P';
    }
    public char getMylist(int row, int col) {
        return my_list[row][col];
    }
    public boolean ifFilled(){
        boolean result = true;
        for(int i=0; i<3; i++){
            for(int j=0; j<3; j++){
                if(getMylist(i,j) != 'P') {
                    result = false;
                }
            }
        }
        return result;
    }
    public void play(){
        boolean filled = false;
        while(!filled){
            Scanner sc = myScanner();
            printStatement("Please enter the row and column number:");
            String rowNum = sc.next();
            if (rowNum.equals("q")) {
                printStatement("Game over with quit!\n");
                break;
            }

            String colNum = sc.next();
            if (colNum.equals("q")) {
                printStatement("Game over with quit!\n");
                break;
            }
            try {
                int row = Integer.parseInt(rowNum);
                int col = Integer.parseInt(colNum);
                if(row >= 0 && row < 3 && col >= 0 && col < 3){
                    if(getMylist(row, col) == 'P'){
                        printStatement("Place is already filled please try again\n");
                    }
                    else {
                        setMylist(row, col);
                        printBoard();
                        filled = ifFilled();
                    }
                }
                else {
                    printStatement("Out of bounds\n");
                }
            } catch (Exception e1) {
                printStatement("Invalid input!\n");
            }
        }
    }
    public void printStatement(String statement){
        System.out.print(statement);
    }

    public void printBoard(){
        for(int i=0; i<3; i++){
            for(int j=0; j<3; j++){
                if(j==1 || j == 2){
                    System.out.print(" ");
                }
                if(getMylist(i,j) == 'P'){
                    System.out.print(getMylist(i,j));
                } else {
                    System.out.print("-");
                }
            }
            System.out.println();
        }
    }
}

