package pkgTTTBackend;

import static pkgTTTBackend.KDIOManager.*;

public class KDTTTBoard {
    private final int ROW = 3, COL = 3;
    private char[][] ttt_board = new char[ROW][COL];
    private final char machine_char = 'X';
    private final char default_char = '-';
    private final char player_char = 'P';
    private int totalValidentries = 0;
    private char winner_char;

    public KDTTTBoard() {
        for (int k = 0; k < 3; k++) {
            for (int j = 0; j < 3; j++) {
                ttt_board[k][j] = default_char;
            }
        }
    }

    private boolean updateBoard(int row, int col) {
        if (row < 0 || row >= ROW || col < 0 || col >= COL) {
            invalidEntryMessage();
            return false;
        }
        if (ttt_board[row][col] == default_char) {
            ttt_board[row][col] = player_char;
            totalValidentries++;
            if (totalValidentries == ROW * COL) {
                boardCompleteMessage();
                quitGameMessage();
            }
            printBoard(this);
            return true;
        } else {
            cellNotFreeMessage(row, col);
            return false;
        }
    }

    public char[][] getBoard() {
        return ttt_board.clone();
    }

    public void play() {
        boolean done = false;
        while (!done) {
            int[] rowCol = readIntegerInput(2);
            if (rowCol[0] == -10 | rowCol[1] == -10) {
                continue;
            }
            if (rowCol[0] == -1 || rowCol[1] == -1) {
                quitGameMessage();
                break;
            }

            if (updateBoard(rowCol[0], rowCol[1])) {
                if (totalValidentries == ROW * COL) {
                    done = true;
                }
            }
        }
    }

    public void testPlay() {

        updateBoard(0, 0);
        updateBoard(1, 1);
        updateBoard(2, 2);
        updateBoard(1, 1);
        updateBoard(0, 1);
        updateBoard(0, 2);
        updateBoard(1, 0);
        updateBoard(1, 2);
        updateBoard(2, 0);
        updateBoard(2, 1);

    }

    public void clearBoard() {
        pkgTTTBackend.KDTTTBoard my_board = new pkgTTTBackend.KDTTTBoard();
        this.ttt_board = my_board.getBoard();
        this.totalValidentries = my_board.totalValidentries;
    }
}

