package pkgTTTBackend;
import java.util.Random;

import static pkgTTTBackend.KDIOManager.*;
import static pkgTTTBackend.KDSPOT.*;

public class KDMachinePlayer {
    private KDTTTBoard TTTBoard;
    private char[][] tttBoard;

    protected KDMachinePlayer(KDTTTBoard myBoard) {
        this.TTTBoard = myBoard;
        this.tttBoard = TTTBoard.getBoard();
    }

    private boolean playToConclude(char player) {
        for (int i = 0; i < ROW; i++) {
            if (playTheRow(i, player) || playTheCol(i, player)) {
                return true;
            }
        }
        return playTDiag(player) || playLDiag(player);
    }

    private boolean playTheRow(int index, char player) {
        int count = 0, emptyCol = -1;

        for (int col = 0; col < COL; col++) {
            if (tttBoard[index][col] == player) count++;
            else if (tttBoard[index][col] == default_char) emptyCol = col;
        }

        if (count == 2 && emptyCol != -1) {
            tttBoard[index][emptyCol] = machine_char;
            return true;
        }
        return false;
    }

    private boolean playTheCol(int index, char player) {
        int count = 0, emptyRow = -1;

        for (int row = 0; row < ROW; row++) {
            if (tttBoard[row][index] == player) count++;
            else if (tttBoard[row][index] == default_char) emptyRow = row;
        }

        if (count == 2 && emptyRow != -1) {
            tttBoard[emptyRow][index] = machine_char;
            return true;
        }
        return false;
    }

    private boolean playTDiag(char player) {
        int count = 0, emptyIndex = -1;

        for (int i = 0; i < ROW; i++) {
            if (tttBoard[i][i] == player) count++;
            else if (tttBoard[i][i] == default_char) emptyIndex = i;
        }

        if (count == 2 && emptyIndex != -1) {
            tttBoard[emptyIndex][emptyIndex] = machine_char;
            return true;
        }
        return false;
    }

    private boolean playLDiag(char player) {
        int count = 0, emptyIndex = -1;

        for (int i = 0; i < ROW; i++) {
            if (tttBoard[i][COL - 1 - i] == player) count++;
            else if (tttBoard[i][COL - 1 - i] == default_char) emptyIndex = i;
        }

        if (count == 2 && emptyIndex != -1) {
            tttBoard[emptyIndex][COL - 1 - emptyIndex] = machine_char;
            return true;
        }
        return false;
    }

    private boolean playRandomPick() {
        Random rand = new Random();
        while (true) {
            int row = rand.nextInt(ROW);
            int col = rand.nextInt(COL);
            if (tttBoard[row][col] == default_char) {
                tttBoard[row][col] = machine_char;
                return true;
            }
        }
    }

    protected void play() {
        if (playToConclude(player_char)) return; // Block player win
        if (playToConclude(machine_char)) return; // Try to win
        playRandomPick();
    }

    protected int isGameOver() {
        for (int i = 0; i < ROW; i++) {
            if (findRepeatsInRow(i) == COL || findRepeatsInCol(i) == ROW) {
                return GAME_MACHINE;
            }
        }
        if (findRepeatsTDiagonal() == ROW || findRepeatsLDiagonal() == ROW) {
            return GAME_MACHINE;
        }
        return GAME_INCOMPLETE;
    }

    private int findRepeatsInRow(int row) {
        int count = 0;
        for (int j = 0; j < COL; j++) {
            if (tttBoard[row][j] == machine_char) count++;
        }
        return count;
    }

    private int findRepeatsInCol(int col) {
        int count = 0;
        for (int i = 0; i < ROW; i++) {
            if (tttBoard[i][col] == machine_char) count++;
        }
        return count;
    }

    private int findRepeatsTDiagonal() {
        int count = 0;
        for (int i = 0; i < ROW; i++) {
            if (tttBoard[i][i] == machine_char) count++;
        }
        return count;
    }

    private int findRepeatsLDiagonal() {
        int count = 0;
        for (int i = 0; i < ROW; i++) {
            if (tttBoard[i][COL - 1 - i] == machine_char) count++;
        }
        return count;
    }
}

package pkgTTTBackend;

public class KDSPOT {
    public final static int GAME_DRAW = 0;
    public final static int GAME_PLAYER = 1;
    public final static int GAME_MACHINE = 2;
    public final static int GAME_INCOMPLETE = 3;
    public final static int GAME_QUIT = 4;

    public final static char default_char = '-';
    public final static char player_char = 'P';
    public final static char machine_char = 'X';


    public final static int ROW = 3;
    public final static int COL = 3;
}

package pkgTTTBackend;

import static pkgTTTBackend.KDIOManager.*;
import static pkgTTTBackend.KDSPOT.*;
import static pkgTTTBackend.KDMachinePlayer.*;

public class KDTTTBoard {
    protected char[][] ttt_board = new char[ROW][COL];
    private int totalValidentries;
    private char winner_char;

    public KDTTTBoard() {
        clearBoard();
        KDIOManager.initPrompt();
    }

    public void playAgainMessage(){
        KDIOManager.playAgainMessage();
    }

    protected void setWinner_char(char winner_char) {
        this.winner_char = winner_char;
    }

    private boolean updateBoard(int row, int col, char player) {
        if (row < 0 || row >= ROW || col < 0 || col >= COL) {
            invalidEntryMessage();
            return false;
        }
        if (ttt_board[row][col] == default_char) {
            ttt_board[row][col] = player;
            totalValidentries++;
            return true;
        } else {
            cellNotFreeMessage(row, col);
            return false;
        }
    }

    public char[][] getBoard() {
        return ttt_board;
    }

    public int play() {
        boolean gameOver = false;
        KDMachinePlayer machine = new KDMachinePlayer(this);

        while (!gameOver) {
            // Check if the machine already won
            if (machine.isGameOver() == GAME_MACHINE) {
                machineWinMessage();
                setWinner_char(machine_char);
                printBoard(this);
                quitGameMessage();
                gameOver = true;
                return GAME_MACHINE;
            }
            printBoard(this);
            int[] rowCol = readIntegerInput(2);
            if (rowCol[0] == -10 || rowCol[1] == -10) {
                invalidEntryMessage();
                printBoard(this);
                return GAME_INCOMPLETE;
            }
            if (rowCol[0] == -1 || rowCol[1] == -1) {
                printBoard(this);
                quitGameMessage();
                return GAME_QUIT;
            }

            if (updateBoard(rowCol[0], rowCol[1], player_char)) {
                for (int i = 0; i < ROW; i++) {
                    if (ttt_board[i][0] == player_char && ttt_board[i][1] == player_char && ttt_board[i][2] == player_char) {
                        playerWinMessage();
                        setWinner_char(player_char);
                        printBoard(this);
                        gameOver = true;
                        return GAME_PLAYER;
                    }
                }
                for (int i = 0; i < COL; i++) {
                    if (ttt_board[0][i] == player_char && ttt_board[1][i] == player_char && ttt_board[2][i] == player_char) {
                        playerWinMessage();
                        setWinner_char(player_char);
                        printBoard(this);
                        gameOver = true;
                        return GAME_PLAYER;
                    }
                }
                if ((ttt_board[0][0] == player_char && ttt_board[1][1] == player_char && ttt_board[2][2] == player_char) ||
                        (ttt_board[0][2] == player_char && ttt_board[1][1] == player_char && ttt_board[2][0] == player_char)) {
                    playerWinMessage();
                    setWinner_char(player_char);
                    printBoard(this);
                    gameOver = true;
                    return GAME_PLAYER;
                }
                if (totalValidentries == ROW * COL) {
                    gameDrawMessage();
                    printBoard(this);
                    quitGameMessage();
                    return GAME_DRAW;
                }
                // Machine plays
                machine.play();
                totalValidentries++;
            }
        }
        return GAME_INCOMPLETE;
    }

    public void clearBoard() {
        for (int k = 0; k < ROW; k++) {
            for (int j = 0; j < COL; j++) {
                ttt_board[k][j] = default_char;
            }
        }
        totalValidentries = 0;
    }
}

