package pkgKDRenderEngine;

import org.joml.Matrix4f;
import org.lwjgl.opengl.GL;
import org.lwjgl.BufferUtils;
import pkgKDUtils.KDWindowManager;
import java.nio.FloatBuffer;
import java.nio.IntBuffer;

import static org.lwjgl.glfw.GLFW.glfwPollEvents;
import static org.lwjgl.opengl.GL11.*;
import static org.lwjgl.opengl.GL20.*;

public class KDRenderer {
    private KDWindowManager myWM;
    private Matrix4f viewProjMatrix = new Matrix4f();
    private FloatBuffer myFloatBuffer = BufferUtils.createFloatBuffer(16);
    private int vpMatLocation;
    private int renderColorLocation;
    private int shaderProgram;
    private int OFFSET, PADDING,SIZE;
    private final int NUM_COLS = 500;
    private final int NUM_ROWS = 500;
    private final int VPT = 4;
    private final int IPV = 6;
    private final int FPV = 2;


    public KDRenderer(KDWindowManager windowManager) {
        this.myWM = windowManager;
        myWM.updateContextToThis();
        GL.createCapabilities();
    }
    public void render(final int offset, final int padding, final int size, final int numRows, final int numCols) {
        OFFSET = offset;
        PADDING = padding;
        SIZE = size;
        myWM.updateContextToThis();
        initOpenGL();
        renderLoop();
        myWM.destroyGlfwWindow();
    }
    private void renderLoop(){
        while(!myWM.isGlfwWindowClosed()){
            glfwPollEvents();
            glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
            renderObject();
            myWM.swapBuffers();
        }
    }
    private void initOpenGL() {
        glClearColor(0.0f, 0.0f, 1.0f, 1.0f);  // Set background to black

        GL.createCapabilities();
        glEnable(GL_DEPTH_TEST);
        glEnable(GL_CULL_FACE);
        int[] windowSize = myWM.getWindowSize();

        glViewport(0, 0, windowSize[0], windowSize[1]);

        this.shaderProgram = glCreateProgram();

        // Vertex Shader
        int vs = glCreateShader(GL_VERTEX_SHADER);
        glShaderSource(vs,
                "#version 330 core\n" +
                        "layout(location = 0) in vec2 position;\n" +
                        "uniform mat4 viewProjMatrix;\n" +
                        "void main(void) {\n" +
                        " gl_Position = viewProjMatrix * vec4(position, 0.0, 1.0);\n" +
                        "}");
        glCompileShader(vs);
        checkShaderCompile(vs);
        glAttachShader(shaderProgram, vs);

        // Fragment Shader
        int fs = glCreateShader(GL_FRAGMENT_SHADER);
        glShaderSource(fs,
                "#version 330 core\n" +
                        "out vec4 fragColor;\n" +
                        "void main(void) {\n" +
                        " fragColor = vec4(0.6, 0.7, 0.1, 1.0);\n" +
                        "}");
        glCompileShader(fs);
        checkShaderCompile(fs);
        glAttachShader(shaderProgram, fs);

        glLinkProgram(shaderProgram);
        glUseProgram(shaderProgram);

        vpMatLocation = glGetUniformLocation(shaderProgram, "viewProjMatrix");
    }

    // Debug function to check shader compilation errors
    private void checkShaderCompile(int shader) {
        int status = glGetShaderi(shader, GL_COMPILE_STATUS);
        if (status == GL_FALSE) {
            String infoLog = glGetShaderInfoLog(shader);
            throw new RuntimeException("Shader compilation failed: " + infoLog);
        }
    }

    private void renderObject() {
        // Generate the vertex and index buffer only once
        int vbo = glGenBuffers();
        int ibo = glGenBuffers();

        int numRows = myWM.getWindowSize()[1] / (SIZE + PADDING);
        int numCols = myWM.getWindowSize()[0] / (SIZE + PADDING);

       // System.out.println("Rendering Tiles: Rows = " + numRows + ", Cols = " + numCols);

        float[] vertices = generateTilesVertices(numRows, numCols);
        int[] indices = generateTilesIndices(numRows, numCols);

        // Upload vertex data
        glBindBuffer(GL_ARRAY_BUFFER, vbo);
        FloatBuffer verticesBuffer = BufferUtils.createFloatBuffer(vertices.length);
        verticesBuffer.put(vertices).flip();
        glBufferData(GL_ARRAY_BUFFER, verticesBuffer, GL_STATIC_DRAW);

        glEnableVertexAttribArray(0);
        glVertexAttribPointer(0, 2, GL_FLOAT, false, 2 * Float.BYTES, 0);

        // Upload index data
        glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, ibo);
        IntBuffer indexBuffer = BufferUtils.createIntBuffer(indices.length);
        indexBuffer.put(indices).flip();
        glBufferData(GL_ELEMENT_ARRAY_BUFFER, indexBuffer, GL_STATIC_DRAW);

        // Set up projection matrix (Fix to match window coordinates)
        viewProjMatrix.setOrtho(0, myWM.getWindowSize()[0], myWM.getWindowSize()[1], 0, -1, 1);
        glUniformMatrix4fv(vpMatLocation, false, viewProjMatrix.get(myFloatBuffer));

        glPolygonMode(GL_FRONT_AND_BACK, GL_FILL);
        glDrawElements(GL_TRIANGLES, indices.length, GL_UNSIGNED_INT, 0);

        glDisableVertexAttribArray(0);
        glBindBuffer(GL_ARRAY_BUFFER, 0);
        glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, 0);
    }


    private float[] generateTilesVertices(final int rowTiles, final int colTiles) {
        int totalVertices = rowTiles * colTiles * VPT * FPV;
        float[] vertices = new float[totalVertices];
        int index = 0;

        float startX = OFFSET;
        float startY = myWM.getWindowSize()[1] - OFFSET;  // Start from top-left

        for (int row = 0; row < rowTiles; row++) {
            for (int col = 0; col < colTiles; col++) {
                float xmin = startX + col * (SIZE + PADDING);
                float ymin = startY - row * (SIZE + PADDING);

                // Store vertices in correct order
                vertices[index++] = xmin;
                vertices[index++] = ymin;  // Top-left
                vertices[index++] = xmin + SIZE;
                vertices[index++] = ymin;  // Top-right
                vertices[index++] = xmin + SIZE;
                vertices[index++] = ymin - SIZE;  // Bottom-right
                vertices[index++] = xmin;
                vertices[index++] = ymin - SIZE;  // Bottom-left
            }
        }
        return vertices;
    }

    private int[] generateTilesIndices(final int rows, final int cols) {
        int totalIndices = rows * cols * IPV;
        int[] indices = new int[totalIndices];
        int index = 0;

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                int tileNum = row * cols + col;
                int startIV = VPT * tileNum;

                indices[index++] = startIV;
                indices[index++] = startIV + 1;
                indices[index++] = startIV + 2;
                indices[index++] = startIV;
                indices[index++] = startIV + 2;
                indices[index++] = startIV + 3;
            }
        }
        return indices;
    }

}

