package pkgKDUtils;

import java.io.*;
import java.util.Random;
import java.util.Scanner;

public class KDPingPongArray {
    private int[][] liveArray;
    private int[][] nextArray;
    private final int rows;
    private final int cols;
    private final int randMin;
    private final int randMax;
    private final Random random;
    private int defaultValue;



    public KDPingPongArray(int numRows, int numCols, int randMin, int randMax) {
        this.rows = numRows;
        this.cols = numCols;
        this.randMin = randMin;
        this.randMax = randMax;
        this.random = new Random();

        liveArray = new int[rows][cols];
        nextArray = new int[rows][cols];

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                nextArray[row][col] = random.nextInt(randMin, randMax);
            }
        }
    }

    public void swapLiveAndNext() {
        int[][] temp = liveArray;
        liveArray = nextArray;
        nextArray = temp;
    }

    public void set(int row, int col, int newValue) {
        if (row >= 0 && row < rows && col >= 0 && col < cols) {
            nextArray[row][col] = newValue; // Modify only the nextArray
        } else {
            System.err.println("Invalid index: (" + row + ", " + col + ")");
        }
    }
    public void setCell(int row, int col, int newValue) {
        set(row,col,newValue);
    }

    public void randomize() {
        copyToNextArray();
        randomizeViaFisherYatesKnuth();
    }

    public void randomizeViaFisherYatesKnuth() {
        copyToNextArray();
        for (int row = rows - 1; row >= 0; row--) {
            for (int col = cols - 1; col >= 0; col--) {
                int currentPos = row * cols + col;
                int randomPos = random.nextInt(currentPos + 1);
                int randomRow = randomPos / cols;
                int randomCol = randomPos % cols;

                int temp = nextArray[row][col];
                nextArray[row][col] = nextArray[randomRow][randomCol];
                nextArray[randomRow][randomCol] = temp;
            }
        }
    }

    public void randomizeInRange() {
        int value = 0;
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                nextArray[row][col] = value;
                value++;
            }
        }

        randomizeViaFisherYatesKnuth();
    }

    public void save(String dataFileName) {
        try (PrintWriter writer = new PrintWriter(new FileWriter(dataFileName))) {
            writeArrayToFile(writer);
            System.out.println("Wrote file: " + dataFileName);
        } catch (IOException e) {
            System.err.println("Error writing to file: " + e.getMessage());
        }
    }

    public void save() {
        save("ppa_data.txt");
    }

    private void writeArrayToFile(PrintWriter writer) {
        writer.println(defaultValue);
        writer.println(rows + " " + cols);
        for (int row = 0; row < rows; row++) {
            writer.print(row);
            for (int col = 0; col < cols; col++) {
                writer.print(" " + (liveArray[row][col] != 0 ? liveArray[row][col] : defaultValue));
            }
            writer.println();
        }
    }


    public void loadFile(String dataFileName) {
        try {
            File file = new File(dataFileName);
            if (!file.exists()) {
                InputStream is = getClass().getClassLoader().getResourceAsStream(dataFileName);
                if (is == null) {
                    System.err.println("File not found: " + dataFileName);
                    return;
                }
                Scanner scanner = new Scanner(is);
                processFileData(scanner);
            } else {
                Scanner scanner = new Scanner(file);
                processFileData(scanner);
            }
        } catch (Exception e) {
            System.err.println("Error loading file: " + e.getMessage());
        }
    }

    private void processFileData(Scanner scanner) {
        defaultValue = scanner.nextInt();

        int fileRows = scanner.nextInt();
        int fileCols = scanner.nextInt();

        int[][] newLiveArray = new int[rows][cols];
        int[][] newNextArray = new int[rows][cols];

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                newLiveArray[row][col] = defaultValue;
                newNextArray[row][col] = defaultValue;
            }
        }

        while (scanner.hasNextInt()) {
            int row = scanner.nextInt();
            if (row < rows) {
                int col = 0;
                while (scanner.hasNextInt() && col < cols) {
                    int value = scanner.nextInt();
                    if (col < cols) {
                        newNextArray[row][col] = value;
                    }
                    col++;
                }
            }
        }

        nextArray = newNextArray;
        liveArray = newLiveArray;
        scanner.close();
    }

    private record RCPair(int row, int col) {
        RCPair {
            row = row;
            col = col;
        }
    }

    public RCPair[] getNearestNeighborsArray(int orgRow, int orgCol) {
        RCPair[] neighbors = new RCPair[8];
        int index = 0;

        for (int rowOffset = -1; rowOffset <= 1; rowOffset++) {
            for (int colOffset = -1; colOffset <= 1; colOffset++) {
                if (rowOffset == 0 && colOffset == 0) continue;

                int nRow = (orgRow + rowOffset + rows) % rows;
                int nCol = (orgCol + colOffset + cols) % cols;

                neighbors[index++] = new RCPair(nRow, nCol);
            }
        }

        return neighbors;
    }
    public void updateToNearestNNSum() {
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                RCPair[] neighbors = getNearestNeighborsArray(row, col);
                int sum = 0;

                for (RCPair neighbor : neighbors) {
                    sum += liveArray[neighbor.row()][neighbor.col()];
                }

                nextArray[row][col] = sum;
            }
        }
    }

    public int[][] getArray() {
        int[][] copy = new int[rows][cols];
        for (int row = 0; row < rows; row++) {
            System.arraycopy(liveArray[row], 0, copy[row], 0, cols);
        }
        return copy;
    }

    public void copyToNextArray() {
        for (int row = 0; row < rows; row++) {
            System.arraycopy(liveArray[row], 0, nextArray[row], 0, cols);
        }
    }

    public void printArray() {
        for (int row = 0; row < rows; row++) {
            System.out.print(row + " ");
            for (int col = 0; col < cols; col++) {
                System.out.print(liveArray[row][col] + " ");
            }
            System.out.println();
        }
    }
}

