package pkgKDRenderEngine;

import pkgKDUtils.KDPingPongArray;

import java.util.Random;
import java.util.List;
import java.util.ArrayList;
import java.util.Collections;

public class KDGoLArray extends KDPingPongArray {
    public static final int DEAD = 0;
    public static final int LIVE = 1;

    // Constructor 1: basic, assumes 20% alive
    public KDGoLArray(int numRows, int numCols) {
        this(numRows, numCols, (int)Math.round(numRows * numCols * 0.2));
    }

    // Constructor 2: initialize with specific live cells
    public KDGoLArray(int numRows, int numCols, int numLiveCells) {
        super(numRows, numCols, 0, 1); // random [0,1) => all 0s in nextArray

        int totalCells = numRows * numCols;
        numLiveCells = Math.max(0, Math.min(numLiveCells, totalCells));

        List<Integer> cells = new ArrayList<>(totalCells);
        for (int i = 0; i < numLiveCells; i++) cells.add(LIVE);
        for (int i = numLiveCells; i < totalCells; i++) cells.add(DEAD);

        Collections.shuffle(cells, new Random());

        int index = 0;
        for (int row = 0; row < numRows; row++) {
            for (int col = 0; col < numCols; col++) {
                setCell(row, col, cells.get(index++)); // populates nextArray
            }
        }

        swapLiveAndNext(); // promote initialized state
    }

    // Constructor 3: load from file
    public KDGoLArray(String myDataFile) {
        super(16, 16, 0, 2); // default fallback size
        loadFile(myDataFile); // populates nextArray
        swapLiveAndNext();    // promote loaded file to liveArray
    }

    // Game of Life update logic
    public void updateToNextGeneration() {
        int[][] current = getArray(); // snapshot of liveArray
        int rows = current.length;
        int cols = current[0].length;

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                int liveNeighbors = countLiveNeighbors(current, row, col, rows, cols);
                int currentState = current[row][col];

                if (currentState == LIVE) {
                    setCell(row, col, (liveNeighbors < 2 || liveNeighbors > 3) ? DEAD : LIVE);
                } else {
                    setCell(row, col, (liveNeighbors == 3) ? LIVE : DEAD);
                }
            }
        }

        swapLiveAndNext();
    }

    // DRY utility method for counting live neighbors (wrap-around logic)
    private int countLiveNeighbors(int[][] grid, int row, int col, int rows, int cols) {
        int count = 0;
        for (int dRow = -1; dRow <= 1; dRow++) {
            for (int dCol = -1; dCol <= 1; dCol++) {
                if (dRow == 0 && dCol == 0) continue;
                int nRow = (row + dRow + rows) % rows;
                int nCol = (col + dCol + cols) % cols;
                if (grid[nRow][nCol] == LIVE) count++;
            }
        }
        return count;
    }
}



package pkgKDRenderEngine;



import org.joml.Matrix4f;
import org.lwjgl.opengl.GL;
import org.lwjgl.BufferUtils;
import pkgKDUtils.KDGeometryManager;
import pkgKDUtils.KDWindowManager;
import java.nio.FloatBuffer;
import java.nio.IntBuffer;

import static org.lwjgl.glfw.GLFW.glfwPollEvents;
import static org.lwjgl.opengl.GL11.*;
import static org.lwjgl.opengl.GL20.*;

public class KDRenderer {
    private KDWindowManager myWM;
    private Matrix4f viewProjMatrix = new Matrix4f();
    private FloatBuffer myFloatBuffer = BufferUtils.createFloatBuffer(16);
    private int vpMatLocation;
    private int renderColorLocation;
    private int shaderProgram;
    private int OFFSET, PADDING,SIZE;
    private final int NUM_COLS = 16;
    private final int NUM_ROWS = 16;
    private final int VPT = 4;
    private final int IPV = 6;
    private final int FPV = 2;
    private KDGoLArray golArray;
    private KDGeometryManager gm;
    private FloatBuffer vBuffer;
    private int vbo, ibo;



    public KDRenderer(KDWindowManager wm, KDGoLArray golArray, int offset, int size, int padding) {
        this.myWM = wm;
        this.golArray = golArray;
        this.OFFSET = offset;
        this.SIZE = size;
        this.PADDING = padding;
        this.gm = new KDGeometryManager(
                golArray.getArray().length,
                golArray.getArray()[0].length,
                OFFSET, SIZE, PADDING,
                myWM.getWindowSize()
        );
    }
    public void render(final int offset, final int padding, final int size, final int numRows, final int numCols) {
        OFFSET = offset;
        PADDING = padding;
        SIZE = size;
        myWM.updateContextToThis();
        initOpenGL();
        renderLoop();
        myWM.destroyGlfwWindow();
    }
    private void renderLoop(){
        while(!myWM.isGlfwWindowClosed()){
            glfwPollEvents();
            glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
            renderObjects();
            myWM.swapBuffers();
        }
    }
    public void initOpenGL() {
        glClearColor(0.0f, 0.0f, 1.0f, 1.0f);  // Set background to black

        GL.createCapabilities();
        glEnable(GL_DEPTH_TEST);
        glEnable(GL_CULL_FACE);
        int[] windowSize = myWM.getWindowSize();

        glViewport(0, 0, windowSize[0], windowSize[1]);

        this.shaderProgram = glCreateProgram();

        // Vertex Shader
        int vs = glCreateShader(GL_VERTEX_SHADER);
        glShaderSource(vs,
                "#version 330 core\n" +
                        "layout(location = 0) in vec2 position;\n" +
                        "uniform mat4 viewProjMatrix;\n" +
                        "void main(void) {\n" +
                        " gl_Position = viewProjMatrix * vec4(position, 0.0, 1.0);\n" +
                        "}");
        glCompileShader(vs);
        checkShaderCompile(vs);
        glAttachShader(shaderProgram, vs);

        // Fragment Shader
        int fs = glCreateShader(GL_FRAGMENT_SHADER);
        glShaderSource(fs,
                "#version 330 core\n" +
                        "out vec4 fragColor;\n" +
                        "void main(void) {\n" +
                        " fragColor = vec4(0.6, 0.7, 0.1, 1.0);\n" +
                        "}");
        glCompileShader(fs);
        checkShaderCompile(fs);
        glAttachShader(shaderProgram, fs);

        glLinkProgram(shaderProgram);
        glUseProgram(shaderProgram);

        vpMatLocation = glGetUniformLocation(shaderProgram, "viewProjMatrix");
    }

    // Debug function to check shader compilation errors
    private void checkShaderCompile(int shader) {
        int status = glGetShaderi(shader, GL_COMPILE_STATUS);
        if (status == GL_FALSE) {
            String infoLog = glGetShaderInfoLog(shader);
            throw new RuntimeException("Shader compilation failed: " + infoLog);
        }
    }

    public void renderObjects() {
        int totalTiles = golArray.getArray().length * golArray.getArray()[0].length;
        float[] vertices = new float[totalTiles * 8];
        int[] indices = gm.generateTileIndices(totalTiles);

        vbo = glGenBuffers();
        ibo = glGenBuffers();

        glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, ibo);
        IntBuffer ib = BufferUtils.createIntBuffer(indices.length);
        ib.put(indices).flip();
        glBufferData(GL_ELEMENT_ARRAY_BUFFER, ib, GL_STATIC_DRAW);

        vBuffer = BufferUtils.createFloatBuffer(vertices.length);

        while (!myWM.isGlfwWindowClosed()) {
            glfwPollEvents();
            glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);

            golArray.updateToNextGeneration();
            golArray.swapLiveAndNext();

            vertices = new float[totalTiles * 8]; // Reset
            gm.generateTilesVertices(golArray, vertices);
            vBuffer.clear();
            vBuffer.put(vertices).flip();

            glBindBuffer(GL_ARRAY_BUFFER, vbo);
            glBufferData(GL_ARRAY_BUFFER, vBuffer, GL_DYNAMIC_DRAW);

            glEnableVertexAttribArray(0);
            glVertexAttribPointer(0, 2, GL_FLOAT, false, 2 * Float.BYTES, 0);

            viewProjMatrix.setOrtho(0, myWM.getWindowSize()[0], myWM.getWindowSize()[1], 0, -1, 1);
            glUniformMatrix4fv(vpMatLocation, false, viewProjMatrix.get(myFloatBuffer));

            glDrawElements(GL_TRIANGLES, indices.length, GL_UNSIGNED_INT, 0);

            glDisableVertexAttribArray(0);
            glBindBuffer(GL_ARRAY_BUFFER, 0);
            myWM.swapBuffers();

            try { Thread.sleep(100); } catch (InterruptedException ignored) {}
        }
    }



    private float[] generateTilesVertices(final int rowTiles, final int colTiles) {
        int totalVertices = rowTiles * colTiles * VPT * FPV;
        float[] vertices = new float[totalVertices];
        int index = 0;

        float startX = OFFSET;
        float startY = myWM.getWindowSize()[1] - OFFSET;  // Start from top-left

        for (int row = 0; row < rowTiles; row++) {
            for (int col = 0; col < colTiles; col++) {
                float xmin = startX + col * (SIZE + PADDING);
                float ymin = startY - row * (SIZE + PADDING);

                // Store vertices in correct order
                vertices[index++] = xmin;
                vertices[index++] = ymin;  // Top-left
                vertices[index++] = xmin + SIZE;
                vertices[index++] = ymin;  // Top-right
                vertices[index++] = xmin + SIZE;
                vertices[index++] = ymin - SIZE;  // Bottom-right
                vertices[index++] = xmin;
                vertices[index++] = ymin - SIZE;  // Bottom-left
            }
        }
        return vertices;
    }

    private int[] generateTilesIndices(final int rows, final int cols) {
        int totalIndices = rows * cols * IPV;
        int[] indices = new int[totalIndices];
        int index = 0;

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                int tileNum = row * cols + col;
                int startIV = VPT * tileNum;

                indices[index++] = startIV;
                indices[index++] = startIV + 1;
                indices[index++] = startIV + 2;
                indices[index++] = startIV;
                indices[index++] = startIV + 2;
                indices[index++] = startIV + 3;
            }
        }
        return indices;
    }

}

package pkgKDUtils;

import pkgKDRenderEngine.KDGoLArray;

public class KDGeometryManager {
    private int rows, cols, offset, size, padding;
    private int winWidth, winHeight;

    public KDGeometryManager(int maxRows, int maxCols, int offset, int size, int padding, int[] winDims) {
        this.rows = maxRows;
        this.cols = maxCols;
        this.offset = offset;
        this.size = size;
        this.padding = padding;
        this.winWidth = winDims[0];
        this.winHeight = winDims[1];
    }

    public float[] generateTilesVertices(int rowTiles, int colTiles) {
        float[] vertices = new float[rowTiles * colTiles * 4 * 2];  // 4 vertices per cell, each vertex = 2 coords
        int index = 0;

        for (int row = 0; row < rowTiles; row++) {
            for (int col = 0; col < colTiles; col++) {
                float xmin = offset + col * (size + padding);
                float ymin = winHeight - (offset + row * (size + padding));

                index = fillArrayWithTileVertices(vertices, index, xmin, ymin);
            }
        }

        return vertices;
    }

    private int fillArrayWithTileVertices(float[] vertices, int index, float xmin, float ymin) {
        vertices[index++] = xmin;         vertices[index++] = ymin;
        vertices[index++] = xmin + size;  vertices[index++] = ymin;
        vertices[index++] = xmin + size;  vertices[index++] = ymin - size;
        vertices[index++] = xmin;         vertices[index++] = ymin - size;
        return index;
    }

    public int[] generateTileIndices(int totalTiles) {
        int[] indices = new int[totalTiles * 6]; // 2 triangles per tile
        int idx = 0, v = 0;
        for (int i = 0; i < totalTiles; i++) {
            indices[idx++] = v;
            indices[idx++] = v + 1;
            indices[idx++] = v + 2;
            indices[idx++] = v;
            indices[idx++] = v + 2;
            indices[idx++] = v + 3;
            v += 4;
        }
        return indices;
    }

    public boolean generateTilesVertices(KDGoLArray myGoLA, float[] vertices) {
        int idx = 0;
        int[][] array = myGoLA.getArray();
        for (int row = 0; row < array.length; row++) {
            for (int col = 0; col < array[0].length; col++) {
                if (array[row][col] == KDGoLArray.LIVE) {
                    float xmin = offset + col * (size + padding);
                    float ymin = winHeight - (offset + row * (size + padding));
                    idx = fillArrayWithTileVertices(vertices, idx, xmin, ymin);
                }
            }
        }
        return true;
    }
}


