package pkgKDUtils;
import java.io.*;
import java.util.*;
import java.util.Random;


public class KDPingPongArray {
    private int[][] liveArray;
    private int[][] nextArray;
    private int numRows, numCols;
    private int randMin, randMax;

    public KDPingPongArray(int numRows, int numCols, int randMin, int randMax) {
        this.numRows = numRows;
        this.numCols = numCols;
        this.randMin = randMin;
        this.randMax = randMax;
        liveArray = new int[numRows][numCols];
        nextArray = new int[numRows][numCols];
    }

    public void randomizeViaFisherYatesKnuth() {
        Random rand = new Random();
        int size = numRows * numCols;
        List<Integer> values = new ArrayList<>();
        for (int i = 0; i < size; i++) {
            values.add(randMin + rand.nextInt(randMax - randMin));
        }
        Collections.shuffle(values);

        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < numCols; j++) {
                nextArray[i][j] = values.remove(0);
            }
        }
    }

    public void swapLiveAndNext() {
        int[][] temp = liveArray;
        liveArray = nextArray;
        nextArray = temp;
    }

    public void save(String filename) throws IOException {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(filename))) {
            writer.write("default_int\n");
            writer.write(numRows + " " + numCols + "\n");
            for (int i = 0; i < numRows; i++) {
                writer.write(i + " ");
                for (int j = 0; j < numCols; j++) {
                    writer.write(liveArray[i][j] + " ");
                }
                writer.newLine();
            }
        }
    }

    public void loadFile(String filename) throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader(filename))) {
            reader.readLine(); // Skip "default_int"
            String[] dimensions = reader.readLine().split(" ");
            int rows = Integer.parseInt(dimensions[0]);
            int cols = Integer.parseInt(dimensions[1]);
            liveArray = new int[rows][cols];

            String line;
            while ((line = reader.readLine()) != null) {
                String[] parts = line.split(" ");
                int row = Integer.parseInt(parts[0]);
                for (int i = 1; i < parts.length; i++) {
                    liveArray[row][i - 1] = Integer.parseInt(parts[i]);
                }
            }
        }
    }

    public record RCPair(int row, int col) {}

    public RCPair[] getNearestNeighborsArray(int orgRow, int orgCol) {
        int[] dRow = {-1, -1, -1, 0, 0, 1, 1, 1};
        int[] dCol = {-1, 0, 1, -1, 1, -1, 0, 1};
        RCPair[] neighbors = new RCPair[8];

        for (int i = 0; i < 8; i++) {
            int newRow = (orgRow + dRow[i] + numRows) % numRows;
            int newCol = (orgCol + dCol[i] + numCols) % numCols;
            neighbors[i] = new RCPair(newRow, newCol);
        }
        return neighbors;
    }

    public void updateToNNSum() {
        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < numCols; j++) {
                int sum = 0;
                for (RCPair neighbor : getNearestNeighborsArray(i, j)) {
                    sum += liveArray[neighbor.row()][neighbor.col()];
                }
                nextArray[i][j] = sum;
            }
        }
    }

    public void set(int row, int col, int newValue) {
        nextArray[row][col] = newValue;
    }

    public int[][] getArray() {
        int[][] copy = new int[numRows][numCols];
        for (int i = 0; i < numRows; i++) {
            copy[i] = Arrays.copyOf(liveArray[i], numCols);
        }
        return copy;
    }

    public void copyToNextArray() {
        for (int i = 0; i < numRows; i++) {
            nextArray[i] = Arrays.copyOf(liveArray[i], numCols);
        }
    }
}

