package pkgTTTBackend;
import java.util.Random;

import static pkgTTTBackend.KDIOManager.*;
import static pkgTTTBackend.KDSPOT.*;
import static pkgTTTBackend.KDTTTBoard.*;

public class KDMachinePlayer {
    private KDTTTBoard TTTBoard;
    private char[][] tttBoard;
    protected KDMachinePlayer(KDTTTBoard myBoard) {
        this.TTTBoard= myBoard;
        this.tttBoard = TTTBoard.getBoard();
    }
    public int play(){
        int gameState = isGameOver();
        if (gameState == GAME_INCOMPLETE || gameState == GAME_MACHINE) {
            return gameState;
        }
        if(playToConclude(machine_char)){
            TTTBoard.setWinner_char(machine_char);
            return GAME_MACHINE;
        }
        if(playToConclude(player_char)){
            return GAME_INCOMPLETE;
        }
        for(int i =0; i < ROW; i++){
            if(playTheRow(i) || playTheCol(i)){
                return GAME_INCOMPLETE;
            }
        }
        if(playTDiag()|| playLDiag()){
            return GAME_INCOMPLETE;
        }
        playRandomPick();
        return GAME_INCOMPLETE;
    }
    private boolean playToConclude(char player) {
        for (int i = 0; i < ROW; i++) {
            if (playTheRow(i)) {
                return true;
            }
            if (playTheCol(i)) {
                return true;
            }
        }
        return playTDiag() || playLDiag();
    }


    private boolean playTheRow(int index) {
        int countMachine = 0, countPlayer = 0, emptyCol = -1;

        for (int col = 0; col < COL; col++) {
            if (tttBoard[index][col] == machine_char) countMachine++;
            else if (tttBoard[index][col] == player_char) countPlayer++;
            else if (tttBoard[index][col] == default_char) emptyCol = col;
        }

        if ((countMachine == 2 || countPlayer == 2) && emptyCol != -1) {
            tttBoard[index][emptyCol] = machine_char;
            return true;
        }

        return false;
    }
    private boolean playTheCol(int index) {
        int countMachine = 0, countPlayer = 0, emptyRow = -1;

        for (int row = 0; row < ROW; row++) {
            if (tttBoard[row][index] == machine_char) countMachine++;
            else if (tttBoard[row][index] == player_char) countPlayer++;
            else if (tttBoard[row][index] == default_char) emptyRow = row;
        }

        if ((countMachine == 2 || countPlayer == 2) && emptyRow != -1) {
            tttBoard[emptyRow][index] = machine_char;
            return true;
        }

        return false;
    }
    private boolean playTDiag() {
        int countMachine = 0, countPlayer = 0, emptyIndex = -1;

        for (int i = 0; i < ROW; i++) {
            if (tttBoard[i][i] == machine_char) countMachine++;
            else if (tttBoard[i][i] == player_char) countPlayer++;
            else if (tttBoard[i][i] == default_char) emptyIndex = i;
        }

        if ((countMachine == 2 || countPlayer == 2) && emptyIndex != -1) {
            tttBoard[emptyIndex][emptyIndex] = machine_char;
            return true;
        }

        return false;
    }

    private boolean playLDiag() {
        int countMachine = 0, countPlayer = 0, emptyIndex = -1;

        for (int i = 0; i < ROW; i++) {
            if (tttBoard[i][COL - 1 - i] == machine_char) countMachine++;
            else if (tttBoard[i][COL - 1 - i] == player_char) countPlayer++;
            else if (tttBoard[i][COL - 1 - i] == default_char) emptyIndex = i;
        }

        if ((countMachine == 2 || countPlayer == 2) && emptyIndex != -1) {
            tttBoard[emptyIndex][COL - 1 - emptyIndex] = machine_char;
            return true;
        }

        return false;
    }

    private boolean playRandomPick() {
        int row, col;
        Random rand = new Random();
        while(true){
            row = rand.nextInt(ROW);
            col = rand.nextInt(COL);
            if(tttBoard[row][col] == default_char){
                tttBoard[row][col] = machine_char;
                return true;
            }
        }
    }
    private int findRepeatsInRow(int row, int col) {
        int count =0;
        for(int j=0; j<COL; j++){
            if(tttBoard[row][j] == machine_char){
                count++;
            }
        }
        return count;
    }
    private int findRepeatsInCol(int row, int col) {
        int count =0;
        for(int i=0; i<ROW; i++){
            if(tttBoard[i][col] == machine_char){
                count++;
            }
        }
        return count;
    }
    private int findRepeatsTDiagonal(int row) {
        int count =0;
        for(int i=0; i<ROW; i++){
            if(tttBoard[i][i] == machine_char){
               count++;
            }
        }
        return count;
    }
    private int findRepeatsLDiagonal(int col) {
        int count =0;
        for(int i=0; i<ROW; i++){
            if(tttBoard[i][COL-1-i] == machine_char){
                count++;
            }
        }
        return count;
    }
    protected int isGameOver() {
        for (int i = 0; i < ROW; i++) {
            if (findRepeatsInRow(i, 0) == COL) {
                TTTBoard.setWinner_char(machine_char);
                return GAME_MACHINE;
            }
            if (findRepeatsInCol(0, i) == ROW) {
                TTTBoard.setWinner_char(machine_char);
                return GAME_MACHINE;
            }
        }
        if (findRepeatsTDiagonal(0) == ROW || findRepeatsLDiagonal(0) == ROW) {
            TTTBoard.setWinner_char(machine_char);
            return GAME_MACHINE;
        }   // Check if the player wins
        for (int i = 0; i < ROW; i++) {
            if (findRepeatsInRow(i, 0) == COL) {
                TTTBoard.setWinner_char(player_char);
                return GAME_PLAYER;
            }
            if (findRepeatsInCol(0, i) == ROW) {
                TTTBoard.setWinner_char(player_char);
                return GAME_PLAYER;
            }
        }
        if (findRepeatsTDiagonal(0) == ROW || findRepeatsLDiagonal(0) == ROW) {
            TTTBoard.setWinner_char(player_char);
            return GAME_PLAYER;
        }
        return GAME_INCOMPLETE;
    }
}

