package pkgKDRenderEngine;

import org.joml.Matrix4f;
import org.lwjgl.opengl.GL;
import org.lwjgl.BufferUtils;
import pkgKDUtils.KDWindowManager;
import java.nio.FloatBuffer;
import java.nio.IntBuffer;

import static org.lwjgl.glfw.GLFW.glfwPollEvents;
import static org.lwjgl.opengl.GL11.*;
import static org.lwjgl.opengl.GL20.*;

public class KDRenderer {
    private KDWindowManager myWM;
    private Matrix4f viewProjMatrix = new Matrix4f();
    private FloatBuffer myFloatBuffer = BufferUtils.createFloatBuffer(16);
    private int vpMatLocation;
    private int renderColorLocation;
    private int shaderProgram;
    private int OFFSET, PADDING,SIZE;
    private int NUM_COLS, NUM_ROWS;
    private final int VPT = 4;
    private final int IPV = 6;
    private final int FPV = 2;


    public KDRenderer(KDWindowManager windowManager) {
        this.myWM = windowManager;
    }
    public void render(final int offset, final int padding, final int size, final int numRows, final int numCols) {
        OFFSET = offset;
        PADDING = padding;
        SIZE = size;
        myWM.updateContextToThis();
        initOpenGL();
        renderLoop();
        myWM.destroyGlfwWindow();
    }
    private void renderLoop(){
        while(!myWM.isGlfwWindowClosed()){
            glfwPollEvents();
            glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
            renderObject();
            myWM.swapBuffers();
        }
    }
    private void initOpenGL() {
        glEnable(GL_DEPTH_TEST);
        glEnable(GL_CULL_FACE);
        glViewport(0,0,myWM.getWindowSize()[0],myWM.getWindowSize()[1]);
        glClearColor(0.0f, 0.0f, 1.0f, 1.0f);
        shaderProgram = glCreateProgram();
        int vs = glCreateShader(GL_VERTEX_SHADER);
        glShaderSource(vs, "uniform mat4 viewProjMatrix; void main(){gl_Position = viewProjMatrix* gl_Vertex; }");
        glCompileShader(vs);
        glAttachShader(shaderProgram, vs);
        int fs = glCreateShader(GL_FRAGMENT_SHADER);
        glShaderSource(fs, "uniform vec3 color; void main(){gl_FragColor = vec4(0.6,0.7,0.1,0.1); }");
        glCompileShader(fs);
        glAttachShader(shaderProgram, fs);
        glLinkProgram(shaderProgram);
        glUseProgram(shaderProgram);
        vpMatLocation = glGetUniformLocation(shaderProgram, "viewProjMatrix");
    }
    private void renderObject(){
        int vbo = glGenBuffers();
        int ibo = glGenBuffers();
        float[] vertices = generateTilesVertices(myWM.getWindowSize()[1]/ SIZE, myWM.getWindowSize()[0])/SIZE);
        int [] indices = generateTilesIndices(myWM.getWindowSize()[1]/ SIZE, myWM.getWindowSize()[0])/SIZE);
        glBindBuffer(GL_ARRAY_BUFFER, vbo);
        glBufferData(GL_ARRAY_BUFFER, (FloatBuffer) BufferUtils.createFloatBuffer(vertices.length).put(vertices).flip(), GL_STATIC_DRAW);
        glEnableClientState(GL_VERTEX_ARRAY);
        glBindBuffer(GL_ARRAY_BUFFER, ibo);
        glBufferData(GL_ARRAY_BUFFER,(IntBuffer) BufferUtils.createFloatBuffer(indices.length).put(indices).flip(), GL_STATIC_DRAW);
        glVertexAttribPointer(2, GL_FLOAT, 0, 0L);
        viewProjMatrix.setOrtho(0,myWM.getWindowSize()[0],0,myWM.getWindowSize()[1],  0,  10);
        glUniformMatrix4fv(shaderProgram, false, viewProjMatrix.get(myFloatBuffer));
        glPolygonMode(GL_FRONT_AND_BACK,GL_FILL);
        glDrawArrays(GL_TRIANGLES, indices.length,GL_UNSIGNED_INT,0L);
    }

    private float[] generateTilesVertices(final int rowTiles, final int colTiles) {
        int totalVertices = rowTiles * colTiles * VPT * FPV;
        float[] vertices = new float[totalVertices];
        int index = 0;
        for (int row = 0; row < rowTiles; row++) {
            for (int col = 0; col < colTiles; col++) {
                float xmin = OFFSET + col * (SIZE +PADDING);
                float ymin = myWM.getWindowSize()[1] - (OFFSET + SIZE + row * (SIZE + PADDING));

                vertices[index++] = xmin;
                vertices[index++] = ymin;
                vertices[index++] = xmin + SIZE;
                vertices[index++] = ymin;
                vertices[index++] = xmin + SIZE;
                vertices[index++] = ymin - SIZE;
                vertices[index++] = xmin;
                vertices[index++] = ymin - SIZE;
            }
            return vertices;
        }
    }
    private int[] generateTilesIndices(final int rows, final int cols) {
        int totalIndices = rows * cols * IPV;
        int[] indices = new int[totalIndices];
        int index = 0, startIV;
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                int tileNum = row * cols + col;
                startIV =  VPT * tileNum;
                indices[index++] = startIV;
                indices[index++] = startIV + 1;
                indices[index++] = startIV + 2;
                indices[index++] = startIV;
                indices[index++] = startIV + 2;
                indices[index++] = startIV + 3;
            }
        }
        return indices;
    }
}
