package pkgSlRenderEngine;

import org.joml.Matrix4f;
import org.lwjgl.BufferUtils;
import org.lwjgl.opengl.GL;
import pkgSlUtils.SlWindowManager;

import java.nio.FloatBuffer;
import java.nio.IntBuffer;
import static org.lwjgl.opengl.GL11.*;
import static org.lwjgl.opengl.GL20.*;

public class SlRenderer {
    private final SlWindowManager myWindowManager;
    private final Matrix4f viewProjMatrix = new Matrix4f();
    private final FloatBuffer myFloatBuffer = BufferUtils.createFloatBuffer(16);
    private int vpMatLocation, renderColorLocation, shaderProgram;

    public SlRenderer(SlWindowManager windowManager) {
        this.myWindowManager = windowManager;
    }

    public void render(final int offset, final int padding, final int size, final int numRows, final int numCols) {
        myWindowManager.updateContextToThis();
        initOpenGL();
        renderLoop(offset, padding, size, numRows, numCols);
        myWindowManager.destroyGlfwWindow();
    }

    private void renderLoop(int offset, int padding, int size, int numRows, int numCols) {
        while (!myWindowManager.isGlfwWindowClosed()) {
            glfwPollEvents();
            glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
            renderObjects(offset, padding, size, numRows, numCols);
            myWindowManager.swapBuffers();
        }
    }

    private void initOpenGL() {
        GL.createCapabilities();
        glEnable(GL_DEPTH_TEST);
        glEnable(GL_CULL_FACE);
        glViewport(0, 0, myWindowManager.getWindowSize()[0], myWindowManager.getWindowSize()[1]);
        glClearColor(0.0f, 0.0f, 1.0f, 1.0f);

        shaderProgram = glCreateProgram();
        int vs = glCreateShader(GL_VERTEX_SHADER);
        glShaderSource(vs, "uniform mat4 viewProjMatrix; void main() { gl_Position = viewProjMatrix * gl_Vertex; }");
        glCompileShader(vs);
        glAttachShader(shaderProgram, vs);

        int fs = glCreateShader(GL_FRAGMENT_SHADER);
        glShaderSource(fs, "uniform vec3 color; void main() { gl_FragColor = vec4(0.6, 0.7, 0.1, 1.0); }");
        glCompileShader(fs);
        glAttachShader(shaderProgram, fs);

        glLinkProgram(shaderProgram);
        glUseProgram(shaderProgram);
        vpMatLocation = glGetUniformLocation(shaderProgram, "viewProjMatrix");
    }

    private void renderObjects(int offset, int padding, int size, int numRows, int numCols) {
        int vbo = glGenBuffers();
        int ibo = glGenBuffers();

        float[] vertices = generateTilesVertices(numRows, numCols, offset, padding, size);
        int[] indices = generateTileIndices(numRows, numCols);

        glBindBuffer(GL_ARRAY_BUFFER, vbo);
        glBufferData(GL_ARRAY_BUFFER, (FloatBuffer) BufferUtils.createFloatBuffer(vertices.length).put(vertices).flip(), GL_STATIC_DRAW);
        glEnableClientState(GL_VERTEX_ARRAY);

        glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, ibo);
        glBufferData(GL_ELEMENT_ARRAY_BUFFER, (IntBuffer) BufferUtils.createIntBuffer(indices.length).put(indices).flip(), GL_STATIC_DRAW);
        glVertexPointer(2, GL_FLOAT, 0, 0L);

        viewProjMatrix.setOrtho(0, myWindowManager.getWindowSize()[0], 0, myWindowManager.getWindowSize()[1], 0, 10);
        glUniformMatrix4fv(vpMatLocation, false, viewProjMatrix.get(myFloatBuffer));
        glPolygonMode(GL_FRONT_AND_BACK, GL_FILL);
        glDrawElements(GL_TRIANGLES, indices.length, GL_UNSIGNED_INT, 0L);
    }

    private float[] generateTilesVertices(final int rowTiles, final int columnTiles, int offset, int padding, int size) {
        int totalVertices = rowTiles * columnTiles * 4 * 2;
        float[] vertices = new float[totalVertices];
        int index = 0;

        for (int row = 0; row < rowTiles; row++) {
            for (int col = 0; col < columnTiles; col++) {
                float xmin = offset + col * (size + padding);
                float ymin = myWindowManager.getWindowSize()[1] - (offset + size + row * (size + padding));

                vertices[index++] = xmin;
                vertices[index++] = ymin;
                vertices[index++] = xmin + size;
                vertices[index++] = ymin;
                vertices[index++] = xmin + size;
                vertices[index++] = ymin - size;
                vertices[index++] = xmin;
                vertices[index++] = ymin - size;
            }
        }
        return vertices;
    }

    private int[] generateTileIndices(final int rows, final int cols) {
        int totalIndices = rows * cols * 6;
        int[] indices = new int[totalIndices];
        int index = 0, startIV;

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                int tileNum = row * cols + col;
                startIV = tileNum * 4;

                indices[index++] = startIV;
                indices[index++] = startIV + 1;
                indices[index++] = startIV + 2;
                indices[index++] = startIV;
                indices[index++] = startIV + 2;
                indices[index++] = startIV + 3;
            }
        }
        return indices;
    }
}

