package pkgSlUtils;

import java.io.*;
import java.util.Random;
import java.util.Scanner;

public class XYPingPongArray {
    private int[][] liveArray;
    private int[][] nextArray;
    private final int rows;
    private final int cols;
    private final int randMin;
    private final int randMax;
    private final Random random;
    private int defaultValue;

    /**
     * Constructor for the XYPingPongArray
     * @param numRows Number of rows in the array
     * @param numCols Number of columns in the array
     * @param randMin Minimum value for random generation (inclusive)
     * @param randMax Maximum value for random generation (exclusive)
     */
    public XYPingPongArray(int numRows, int numCols, int randMin, int randMax) {
        this.rows = numRows;
        this.cols = numCols;
        this.randMin = randMin;
        this.randMax = randMax;
        this.random = new Random();

        // Initialize both arrays
        liveArray = new int[rows][cols];
        nextArray = new int[rows][cols];

        // Initialize nextArray with random values (not liveArray)
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                nextArray[row][col] = random.nextInt(randMin, randMax);
            }
        }
    }

    /**
     * Swaps the liveArray and nextArray references
     */
    public void swapLiveAndNext() {
        int[][] temp = liveArray;
        liveArray = nextArray;
        nextArray = temp;
    }

    /**
     * Sets a cell value in the nextArray
     * @param row Row index
     * @param col Column index
     * @param newValue New value to set
     */
    public void setCell(int row, int col, int newValue) {
        nextArray[row][col] = newValue;
    }

    /**
     * Randomizes the nextArray using Fisher-Yates-Knuth algorithm
     * Does not replace the current values, just shuffles them
     */
    public void randomize() {
        // Copy liveArray to nextArray first
        copyToNextArray();

        // Apply Fisher-Yates-Knuth algorithm to nextArray
        for (int row = rows - 1; row > 0; row--) {
            for (int col = cols - 1; col >= 0; col--) {
                // Calculate 1D position
                int currentPos = row * cols + col;

                // Generate a random position from 0 to currentPos
                int randomPos = random.nextInt(currentPos + 1);

                // Convert randomPos back to 2D
                int randomRow = randomPos / cols;
                int randomCol = randomPos % cols;

                // Swap
                int temp = nextArray[row][col];
                nextArray[row][col] = nextArray[randomRow][randomCol];
                nextArray[randomRow][randomCol] = temp;
            }
        }
    }

    /**
     * Randomizes the nextArray with values from 0 to (rows*cols-1)
     * Each number appears exactly once
     * Uses Fisher-Yates-Knuth algorithm
     */
    public void randomizeViaFisherYatesKnuth() {
        // Initialize nextArray with sequential values
        int value = 0;
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                nextArray[row][col] = value % cols;
                value++;
            }
        }

        // Apply Fisher-Yates-Knuth algorithm
        for (int row = rows - 1; row >= 0; row--) {
            for (int col = cols - 1; col >= 0; col--) {
                // Calculate 1D position
                int currentPos = row * cols + col;

                // Generate a random position from 0 to currentPos
                int randomPos = random.nextInt(currentPos + 1);

                // Convert randomPos back to 2D
                int randomRow = randomPos / cols;
                int randomCol = randomPos % cols;

                // Swap
                int temp = nextArray[row][col];
                nextArray[row][col] = nextArray[randomRow][randomCol];
                nextArray[randomRow][randomCol] = temp;
            }
        }
    }

    /**
     * Randomizes the nextArray with values in the range from 0 through (ROWS*COLS - 1)
     * Each number appears exactly once
     */
    public void randomizeInRange() {
        // Initialize nextArray with sequential values
        int value = 0;
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                nextArray[row][col] = value;
                value++;
            }
        }

        // Apply Fisher-Yates-Knuth algorithm
        for (int row = rows - 1; row >= 0; row--) {
            for (int col = cols - 1; col >= 0; col--) {
                // Calculate 1D position
                int currentPos = row * cols + col;

                // Generate a random position from 0 to currentPos
                int randomPos = random.nextInt(currentPos + 1);

                // Convert randomPos back to 2D
                int randomRow = randomPos / cols;
                int randomCol = randomPos % cols;

                // Swap
                int temp = nextArray[row][col];
                nextArray[row][col] = nextArray[randomRow][randomCol];
                nextArray[randomRow][randomCol] = temp;
            }
        }
    }

    /**
     * Saves the liveArray to a file with a specified filename
     * @param dataFileName Name of the file to save to
     */
    public void save(String dataFileName) {
        try (PrintWriter writer = new PrintWriter(new FileWriter(dataFileName))) {
            writer.println(defaultValue);
            writer.println(rows + " " + cols);

            for (int row = 0; row < rows; row++) {
                writer.print(row);
                for (int col = 0; col < cols; col++) {
                    writer.print(" " + liveArray[row][col]);
                }
                writer.println();
            }
            System.out.println("Wrote file: " + dataFileName);
        } catch (IOException e) {
            System.err.println("Error writing to file: " + e.getMessage());
        }
    }

    /**
     * Saves the liveArray to the default file "ppa_data.txt"
     */
    public void save() {
        save("ppa_data.txt");
    }

    /**
     * Loads array data from a file
     * @param dataFileName Name of the file to load from
     */
    public void loadFile(String dataFileName) {
        try (Scanner scanner = new Scanner(new File(dataFileName))) {
            // Read default value
            defaultValue = scanner.nextInt();

            // Read dimensions
            int fileRows = scanner.nextInt();
            int fileCols = scanner.nextInt();

            // Create new arrays with the dimensions from the file
            int[][] newLiveArray = new int[rows][cols];
            int[][] newNextArray = new int[rows][cols];

            // Initialize with default values
            for (int row = 0; row < rows; row++) {
                for (int col = 0; col < cols; col++) {
                    newLiveArray[row][col] = defaultValue;
                    newNextArray[row][col] = defaultValue;
                }
            }

            // Load data from file
            while (scanner.hasNextInt()) {
                int row = scanner.nextInt();
                if (row < rows) {
                    int col = 0;
                    while (scanner.hasNextInt() && col < cols) {
                        int value = scanner.nextInt();
                        if (col < cols) {
                            newNextArray[row][col] = value;
                        }
                        col++;
                    }
                }
            }

            // Replace arrays
            nextArray = newNextArray;
            liveArray = newLiveArray;

        } catch (FileNotFoundException e) {
            System.err.println("File not found: " + e.getMessage());
        }
    }

    /**
     * Private record for row-column pairs
     */
    private record RCPair(int row, int col) {
    }

    /**
     * Gets the nearest neighbors for a given cell
     * Handles wrapping around the edges
     * @param orgRow Original row
     * @param orgCol Original column
     * @return Array of RCPair objects representing the nearest neighbors
     */
    public RCPair[] getNearestNeighborsArray(int orgRow, int orgCol) {
        RCPair[] neighbors = new RCPair[8];
        int index = 0;

        // Check all 8 directions
        for (int rowOffset = -1; rowOffset <= 1; rowOffset++) {
            for (int colOffset = -1; colOffset <= 1; colOffset++) {
                // Skip the center (original cell)
                if (rowOffset == 0 && colOffset == 0) continue;

                // Calculate wrapped indices
                int nRow = (orgRow + rowOffset + rows) % rows;
                int nCol = (orgCol + colOffset + cols) % cols;

                neighbors[index++] = new RCPair(nRow, nCol);
            }
        }

        return neighbors;
    }

    /**
     * Returns a copy of the liveArray
     * @return A copy of the liveArray
     */
    public int[][] getArray() {
        int[][] copy = new int[rows][cols];
        for (int row = 0; row < rows; row++) {
            System.arraycopy(liveArray[row], 0, copy[row], 0, cols);
        }
        return copy;
    }

    /**
     * Copies the liveArray to the nextArray
     */
    public void copyToNextArray() {
        for (int row = 0; row < rows; row++) {
            System.arraycopy(liveArray[row], 0, nextArray[row], 0, cols);
        }
    }

    /**
     * Updates the nextArray with the sum of nearest neighbor elements in the liveArray
     */
    public void updateToNearestNNSum() {
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                RCPair[] neighbors = getNearestNeighborsArray(row, col);
                int sum = 0;

                for (RCPair neighbor : neighbors) {
                    sum += liveArray[neighbor.row()][neighbor.col()];
                }

                nextArray[row][col] = sum;
            }
        }
    }

    /**
     * Prints the liveArray to the console
     */
    public void printArray() {
        for (int row = 0; row < rows; row++) {
            System.out.print(row + " ");
            for (int col = 0; col < cols; col++) {
                System.out.print(liveArray[row][col] + " ");
            }
            System.out.println();
        }
    }
}

