package pkgTTTBackend;

import static pkgTTTBackend.KDIOManager.*;
import static pkgTTTBackend.KDSPOT.*;
import static pkgTTTBackend.KDMachinePlayer.*;

public class KDTTTBoard {
    protected char[][] ttt_board = new char[ROW][COL];
    private int totalValidentries;
    private char winner_char;

    public KDTTTBoard() {
        clearBoard();
    }

    public void playAgainMessage(){
        KDIOManager.playAgainMessage();
    }

    protected void setWinner_char(char winner_char) {
        this.winner_char = winner_char;
    }

    private boolean updateBoard(int row, int col, char player) {
        if (row < 0 || row >= ROW || col < 0 || col >= COL) {
            invalidEntryMessage();
            return false;
        }
        if (ttt_board[row][col] == default_char) {
            ttt_board[row][col] = player;
            totalValidentries++;
            return true;
        } else {
            cellNotFreeMessage(row, col);
            return false;
        }
    }

    public char[][] getBoard() {
        return ttt_board;
    }

    public int play() {
        KDMachinePlayer machine = new KDMachinePlayer(this);
        boolean gameOver = false;

        while (!gameOver) {
            printBoard(this);

            if (checkWinner(machine_char)) {
                machineWinMessage();
                winner_char = machine_char;
                gameOver = true;
                return GAME_MACHINE;
            }

            int[] rowCol = readIntegerInput(2);
            if (rowCol[0] == -10 || rowCol[1] == -10) {
                invalidEntryMessage();
                return GAME_INCOMPLETE;
            }
            if (rowCol[0] == -1 || rowCol[1] == -1) {
                quitGameMessage();
                return GAME_QUIT;
            }

            if (updateBoard(rowCol[0], rowCol[1], player_char)) {
                if (checkWinner(player_char)) {
                    playerWinMessage();
                    winner_char = player_char;
                    gameOver = true;
                    return GAME_PLAYER;
                }
                machine.play();
            }

            if (totalValidentries == ROW * COL) {
                gameDrawMessage();
                printBoard(this);
                return GAME_DRAW;
            }
        }

        errorInPlayMessage();
        return GAME_INCOMPLETE;
    }

    private boolean checkWinner(char player) {
        for (int i = 0; i < ROW; i++) {
            if (ttt_board[i][0] == player && ttt_board[i][1] == player && ttt_board[i][2] == player) {
                return true;
            }
        }
        for (int j = 0; j < COL; j++) {
            if (ttt_board[0][j] == player && ttt_board[1][j] == player && ttt_board[2][j] == player) {
                return true;
            }
        }
        if (ttt_board[0][0] == player && ttt_board[1][1] == player && ttt_board[2][2] == player) {
            return true;
        }
        if (ttt_board[0][2] == player && ttt_board[1][1] == player && ttt_board[2][0] == player) {
            return true;
        }
        return false;
    }

    public void clearBoard() {
        for (int k = 0; k < ROW; k++) {
            for (int j = 0; j < COL; j++) {
                ttt_board[k][j] = default_char;
            }
        }
        totalValidentries = 0;
    }
}

package pkgTTTBackend;

import java.util.Random;
import static pkgTTTBackend.KDSPOT.*;

public class KDMachinePlayer {
    private KDTTTBoard board;
    private Random random;

    public KDMachinePlayer(KDTTTBoard board) {
        this.board = board;
        this.random = new Random();
    }

    public void play() {
        if (board.checkWinner(player_char)) {
            return;
        }

        // Check for a player win and block it
        if (tryToBlockOrWin(player_char)) {
            return;
        }

        // Try to win the game
        if (tryToBlockOrWin(machine_char)) {
            return;
        }

        // If neither can win, play randomly
        playRandom();
    }

    private boolean tryToBlockOrWin(char player) {
        for (int i = 0; i < ROW; i++) {
            for (int j = 0; j < COL; j++) {
                if (board.getBoard()[i][j] == default_char) {
                    board.getBoard()[i][j] = player;
                    if (board.checkWinner(player)) {
                        return true;
                    }
                    board.getBoard()[i][j] = default_char;
                }
            }
        }
        return false;
    }

    private void playRandom() {
        int row, col;
        do {
            row = random.nextInt(ROW);
            col = random.nextInt(COL);
        } while (board.getBoard()[row][col] != default_char);
        board.getBoard()[row][col] = machine_char;
    }
}

