public class KDSPOT {
    public static final int GAME_DRAW = 0;
    public static final int GAME_PLAYER = 1;
    public static final int GAME_MACHINE = 2;
    public static final int GAME_INCOMPLETE = 3;
    public static final int GAME_QUIT = 4;

    public static final char default_char = '-';
    public static final char player_char = 'P';
    public static final char machine_char = 'X';
    public static final int ROW = 3;
    public static final int COL = 3;
}

// Segment 2: Board class
public class KDTTTBoard {
    private char[][] ttt_board;
    private char winner_char;

    public KDTTTBoard() {
        ttt_board = new char[KDSPOT.ROW][KDSPOT.COL];
        clearBoard();
    }

    public int play() {
        Scanner scanner = new Scanner(System.in);
        int turn = KDSPOT.GAME_PLAYER;
        int gameState = KDSPOT.GAME_INCOMPLETE;

        while (gameState == KDSPOT.GAME_INCOMPLETE) {
            printBoard();
            if (turn == KDSPOT.GAME_PLAYER) {
                System.out.println("Enter row and column: ");
                int row = scanner.nextInt();
                int col = scanner.nextInt();
                if (updateBoard(row, col, KDSPOT.player_char)) {
                    turn = KDSPOT.GAME_MACHINE;
                }
            } else {
                KDMachinePlayer machine = new KDMachinePlayer(this);
                machine.play();
                turn = KDSPOT.GAME_PLAYER;
            }
            gameState = isGameOver();
        }
        return gameState;
    }

    public void clearBoard() {
        for (int i = 0; i < KDSPOT.ROW; i++) {
            for (int j = 0; j < KDSPOT.COL; j++) {
                ttt_board[i][j] = KDSPOT.default_char;
            }
        }
    }

    public boolean updateBoard(int row, int col, char symbol) {
        if (row >= 0 && row < KDSPOT.ROW && col >= 0 && col < KDSPOT.COL && ttt_board[row][col] == KDSPOT.default_char) {
            ttt_board[row][col] = symbol;
            return true;
        }
        return false;
    }

    public int isGameOver() {
        for (int i = 0; i < KDSPOT.ROW; i++) {
            if (ttt_board[i][0] != KDSPOT.default_char && ttt_board[i][0] == ttt_board[i][1] && ttt_board[i][1] == ttt_board[i][2]) {
                return ttt_board[i][0] == KDSPOT.player_char ? KDSPOT.GAME_PLAYER : KDSPOT.GAME_MACHINE;
            }
        }
        for (int j = 0; j < KDSPOT.COL; j++) {
            if (ttt_board[0][j] != KDSPOT.default_char && ttt_board[0][j] == ttt_board[1][j] && ttt_board[1][j] == ttt_board[2][j]) {
                return ttt_board[0][j] == KDSPOT.player_char ? KDSPOT.GAME_PLAYER : KDSPOT.GAME_MACHINE;
            }
        }
        return KDSPOT.GAME_INCOMPLETE;
    }

