class KDMachinePlayer {
    private KDTTTBoard board;
    private char[][] tttBoard;

    public KDMachinePlayer(KDTTTBoard board) {
        this.board = board;
        this.tttBoard = board.getBoard();
    }

    public void play() {
        if (playToConclude(KDSPOT.machine_char)) return;
        if (playToConclude(KDSPOT.player_char)) return;
        if (playRandomPick()) return;
    }

    private boolean playToConclude(char player) {
        for (int i = 0; i < KDSPOT.ROW; i++) {
            if (playTheRow(i)) return true;
            if (playTheCol(i)) return true;
        }
        if (playTDiag() || playLDiag()) return true;
        return false;
    }

    private boolean playTheRow(int row) {
        for (int col = 0; col < KDSPOT.COL; col++) {
            if (board.updateBoard(row, col, KDSPOT.machine_char)) return true;
        }
        return false;
    }

    private boolean playTheCol(int col) {
        for (int row = 0; row < KDSPOT.ROW; row++) {
            if (board.updateBoard(row, col, KDSPOT.machine_char)) return true;
        }
        return false;
    }

    private boolean playTDiag() {
        for (int i = 0; i < KDSPOT.ROW; i++) {
            if (board.updateBoard(i, i, KDSPOT.machine_char)) return true;
        }
        return false;
    }

    private boolean playLDiag() {
        for (int i = 0; i < KDSPOT.ROW; i++) {
            if (board.updateBoard(i, KDSPOT.COL - 1 - i, KDSPOT.machine_char)) return true;
        }
        return false;
    }

    private boolean playRandomPick() {
        for (int i = 0; i < KDSPOT.ROW; i++) {
            for (int j = 0; j < KDSPOT.COL; j++) {
                if (board.updateBoard(i, j, KDSPOT.machine_char)) return true;
            }
        }
        return false;
    }
}

