    private char winner_char;

    public KDTTTBoard() {
        for(int k = 0; k < 3; k++) {
            for (int j = 0; j < 3; j++) {
                ttt_board[k][j] = default_char;
            }
        }
    }
    private boolean updateBoard(int row, int col) {
        if(row < 0 || row >= ROW || col < 0 || col >= COL) {
            invalidEntryMessage();
            return false;
        }
        if(ttt_board[row][col] == default_char) {
            ttt_board[row][col] = player_char;
            totalValidentries++;
            if(totalValidentries == ROW*COL){
                boardCompleteMessage();
                quitGameMessage();
            }
            printBoard(this);
            return true;
        }
        else{
            cellNotFreeMessage(row, col);
            return false;
        }
    }
    public char[][] getBoard() {
        return ttt_board.clone();
    }
