        boolean done = false;
        while(!done){
            int [] rowCol = readIntegerInput(2);
            if(rowCol[0] == -10| rowCol[1] == -10){
                continue;
            }
            if (rowCol[0]  == -1|| rowCol[1] == -1 ){
                quitGameMessage();
                break;
            }

            if(updateBoard(rowCol[0], rowCol[1])){
                if(totalValidentries == ROW*COL){
                    done = true;
                }
            }
        }
