package pkgTTTBackend;
import java.util.Random;

import static pkgTTTBackend.KDIOManager.*;
import static pkgTTTBackend.KDSPOT.*;

public class KDMachinePlayer {
    private KDTTTBoard TTTBoard;
    private char[][] tttBoard;

    protected KDMachinePlayer(KDTTTBoard myBoard) {
        this.TTTBoard = myBoard;
        this.tttBoard = TTTBoard.getBoard();
    }

    private boolean playToConclude(char player) {
        for (int i = 0; i < ROW; i++) {
            if (playTheRow(i, player) || playTheCol(i, player)) {
                return true;
            }
        }
        return playTDiag(player) || playLDiag(player);
    }

    private boolean playTheRow(int index, char player) {
        int count = 0, emptyCol = -1;

        for (int col = 0; col < COL; col++) {
            if (tttBoard[index][col] == player) count++;
            else if (tttBoard[index][col] == default_char) emptyCol = col;
        }

        if (count == 2 && emptyCol != -1) {
            tttBoard[index][emptyCol] = machine_char;
            return true;
        }
        return false;
    }

    private boolean playTheCol(int index, char player) {
        int count = 0, emptyRow = -1;

        for (int row = 0; row < ROW; row++) {
            if (tttBoard[row][index] == player) count++;
            else if (tttBoard[row][index] == default_char) emptyRow = row;
        }

        if (count == 2 && emptyRow != -1) {
            tttBoard[emptyRow][index] = machine_char;
            return true;
        }
        return false;
    }

    private boolean playTDiag(char player) {
        int count = 0, emptyIndex = -1;

        for (int i = 0; i < ROW; i++) {
            if (tttBoard[i][i] == player) count++;
            else if (tttBoard[i][i] == default_char) emptyIndex = i;
        }

        if (count == 2 && emptyIndex != -1) {
            tttBoard[emptyIndex][emptyIndex] = machine_char;
            return true;
        }
        return false;
    }

    private boolean playLDiag(char player) {
        int count = 0, emptyIndex = -1;

        for (int i = 0; i < ROW; i++) {
            if (tttBoard[i][COL - 1 - i] == player) count++;
            else if (tttBoard[i][COL - 1 - i] == default_char) emptyIndex = i;
        }

        if (count == 2 && emptyIndex != -1) {
            tttBoard[emptyIndex][COL - 1 - emptyIndex] = machine_char;
            return true;
        }
        return false;
    }

    private boolean playRandomPick() {
        Random rand = new Random();
        while (true) {
            int row = rand.nextInt(ROW);
            int col = rand.nextInt(COL);
            if (tttBoard[row][col] == default_char) {
                tttBoard[row][col] = machine_char;
                return true;
            }
        }
    }

    protected void play() {
        if (playToConclude(player_char)) return; // Block player win
        if (playToConclude(machine_char)) return; // Try to win
        playRandomPick();
    }

    protected int isGameOver() {
        for (int i = 0; i < ROW; i++) {
            if (findRepeatsInRow(i) == COL || findRepeatsInCol(i) == ROW) {
                return GAME_MACHINE;
            }
        }
        if (findRepeatsTDiagonal() == ROW || findRepeatsLDiagonal() == ROW) {
            return GAME_MACHINE;
        }
        return GAME_INCOMPLETE;
    }

    private int findRepeatsInRow(int row) {
        int count = 0;
        for (int j = 0; j < COL; j++) {
            if (tttBoard[row][j] == machine_char) count++;
        }
        return count;
    }

    private int findRepeatsInCol(int col) {
        int count = 0;
        for (int i = 0; i < ROW; i++) {
            if (tttBoard[i][col] == machine_char) count++;
        }
        return count;
    }

    private int findRepeatsTDiagonal() {
        int count = 0;
        for (int i = 0; i < ROW; i++) {
            if (tttBoard[i][i] == machine_char) count++;
        }
        return count;
    }

    private int findRepeatsLDiagonal() {
        int count = 0;
        for (int i = 0; i < ROW; i++) {
            if (tttBoard[i][COL - 1 - i] == machine_char) count++;
        }
        return count;
    }
}

package pkgTTTBackend;

public class KDSPOT {
    public final static int GAME_DRAW = 0;
    public final static int GAME_PLAYER = 1;
    public final static int GAME_MACHINE = 2;
    public final static int GAME_INCOMPLETE = 3;
    public final static int GAME_QUIT = 4;

    public final static char default_char = '-';
    public final static char player_char = 'P';
    public final static char machine_char = 'X';


    public final static int ROW = 3;
    public final static int COL = 3;
}

package pkgTTTBackend;

import static pkgTTTBackend.KDIOManager.*;
import static pkgTTTBackend.KDSPOT.*;
import static pkgTTTBackend.KDMachinePlayer.*;

public class KDTTTBoard {
    protected char[][] ttt_board = new char[ROW][COL];
    private int totalValidentries;
    private char winner_char;

    public KDTTTBoard() {
        clearBoard();
        KDIOManager.initPrompt();
    }

    public void playAgainMessage(){
        KDIOManager.playAgainMessage();
    }

    protected void setWinner_char(char winner_char) {
        this.winner_char = winner_char;
    }

    private boolean updateBoard(int row, int col, char player) {
        if (row < 0 || row >= ROW || col < 0 || col >= COL) {
            invalidEntryMessage();
            return false;
        }
        if (ttt_board[row][col] == default_char) {
            ttt_board[row][col] = player;
            totalValidentries++;
            return true;
        } else {
            cellNotFreeMessage(row, col);
            return false;
        }
    }

    public char[][] getBoard() {
        return ttt_board;
    }

    public int play() {
        boolean gameOver = false;
        KDMachinePlayer machine = new KDMachinePlayer(this);

        while (!gameOver) {
            // Check if the machine already won
            if (machine.isGameOver() == GAME_MACHINE) {
                machineWinMessage();
                setWinner_char(machine_char);
                printBoard(this);
                quitGameMessage();
                gameOver = true;
                return GAME_MACHINE;
            }
            printBoard(this);
            int[] rowCol = readIntegerInput(2);
            if (rowCol[0] == -10 || rowCol[1] == -10) {
                invalidEntryMessage();
                printBoard(this);
                return GAME_INCOMPLETE;
            }
            if (rowCol[0] == -1 || rowCol[1] == -1) {
                printBoard(this);
                quitGameMessage();
                return GAME_QUIT;
            }

            if (updateBoard(rowCol[0], rowCol[1], player_char)) {
                for (int i = 0; i < ROW; i++) {
                    if (ttt_board[i][0] == player_char && ttt_board[i][1] == player_char && ttt_board[i][2] == player_char) {
                        playerWinMessage();
                        setWinner_char(player_char);
                        printBoard(this);
                        gameOver = true;
                        return GAME_PLAYER;
                    }
                }
                for (int i = 0; i < COL; i++) {
                    if (ttt_board[0][i] == player_char && ttt_board[1][i] == player_char && ttt_board[2][i] == player_char) {
                        playerWinMessage();
                        setWinner_char(player_char);
                        printBoard(this);
                        gameOver = true;
                        return GAME_PLAYER;
                    }
                }
                if ((ttt_board[0][0] == player_char && ttt_board[1][1] == player_char && ttt_board[2][2] == player_char) ||
                        (ttt_board[0][2] == player_char && ttt_board[1][1] == player_char && ttt_board[2][0] == player_char)) {
                    playerWinMessage();
                    setWinner_char(player_char);
                    printBoard(this);
                    gameOver = true;
                    return GAME_PLAYER;
                }
                if (totalValidentries == ROW * COL) {
                    gameDrawMessage();
                    printBoard(this);
                    quitGameMessage();
                    return GAME_DRAW;
                }
                // Machine plays
                machine.play();
                totalValidentries++;
            }
        }
        return GAME_INCOMPLETE;
    }

    public void clearBoard() {
        for (int k = 0; k < ROW; k++) {
            for (int j = 0; j < COL; j++) {
                ttt_board[k][j] = default_char;
            }
        }
        totalValidentries = 0;
    }
}

package pkgKDRenderEngine;

import org.joml.Matrix4f;
import org.lwjgl.opengl.GL;
import org.lwjgl.BufferUtils;
import pkgKDUtils.KDWindowManager;
import java.nio.FloatBuffer;
import java.nio.IntBuffer;

import static org.lwjgl.glfw.GLFW.glfwPollEvents;
import static org.lwjgl.opengl.GL11.*;
import static org.lwjgl.opengl.GL20.*;

public class KDRenderer {
    private KDWindowManager myWM;
    private Matrix4f viewProjMatrix = new Matrix4f();
    private FloatBuffer myFloatBuffer = BufferUtils.createFloatBuffer(16);
    private int vpMatLocation;
    private int renderColorLocation;
    private int shaderProgram;
    private int OFFSET, PADDING,SIZE;
    private final int NUM_COLS = 500;
    private final int NUM_ROWS = 500;
    private final int VPT = 4;
    private final int IPV = 6;
    private final int FPV = 2;


    public KDRenderer(KDWindowManager windowManager) {
        this.myWM = windowManager;
        myWM.updateContextToThis();
        GL.createCapabilities();
    }
    public void render(final int offset, final int padding, final int size, final int numRows, final int numCols) {
        OFFSET = offset;
        PADDING = padding;
        SIZE = size;
        myWM.updateContextToThis();
        initOpenGL();
        renderLoop();
        myWM.destroyGlfwWindow();
    }
    private void renderLoop(){
        while(!myWM.isGlfwWindowClosed()){
            glfwPollEvents();
            glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
            renderObject();
            myWM.swapBuffers();
        }
    }
    private void initOpenGL() {
        glClearColor(0.0f, 0.0f, 1.0f, 1.0f);  // Set background to black

        GL.createCapabilities();
        glEnable(GL_DEPTH_TEST);
        glEnable(GL_CULL_FACE);
        int[] windowSize = myWM.getWindowSize();

        glViewport(0, 0, windowSize[0], windowSize[1]);

        this.shaderProgram = glCreateProgram();

        // Vertex Shader
        int vs = glCreateShader(GL_VERTEX_SHADER);
        glShaderSource(vs,
                "#version 330 core\n" +
                        "layout(location = 0) in vec2 position;\n" +
                        "uniform mat4 viewProjMatrix;\n" +
                        "void main(void) {\n" +
                        " gl_Position = viewProjMatrix * vec4(position, 0.0, 1.0);\n" +
                        "}");
        glCompileShader(vs);
        checkShaderCompile(vs);
        glAttachShader(shaderProgram, vs);

        // Fragment Shader
        int fs = glCreateShader(GL_FRAGMENT_SHADER);
        glShaderSource(fs,
                "#version 330 core\n" +
                        "out vec4 fragColor;\n" +
                        "void main(void) {\n" +
                        " fragColor = vec4(0.6, 0.7, 0.1, 1.0);\n" +
                        "}");
        glCompileShader(fs);
        checkShaderCompile(fs);
        glAttachShader(shaderProgram, fs);

        glLinkProgram(shaderProgram);
        glUseProgram(shaderProgram);

        vpMatLocation = glGetUniformLocation(shaderProgram, "viewProjMatrix");
    }

    // Debug function to check shader compilation errors
    private void checkShaderCompile(int shader) {
        int status = glGetShaderi(shader, GL_COMPILE_STATUS);
        if (status == GL_FALSE) {
            String infoLog = glGetShaderInfoLog(shader);
            throw new RuntimeException("Shader compilation failed: " + infoLog);
        }
    }

    private void renderObject() {
        // Generate the vertex and index buffer only once
        int vbo = glGenBuffers();
        int ibo = glGenBuffers();

        int numRows = myWM.getWindowSize()[1] / (SIZE + PADDING);
        int numCols = myWM.getWindowSize()[0] / (SIZE + PADDING);

       // System.out.println("Rendering Tiles: Rows = " + numRows + ", Cols = " + numCols);

        float[] vertices = generateTilesVertices(numRows, numCols);
        int[] indices = generateTilesIndices(numRows, numCols);

        // Upload vertex data
        glBindBuffer(GL_ARRAY_BUFFER, vbo);
        FloatBuffer verticesBuffer = BufferUtils.createFloatBuffer(vertices.length);
        verticesBuffer.put(vertices).flip();
        glBufferData(GL_ARRAY_BUFFER, verticesBuffer, GL_STATIC_DRAW);

        glEnableVertexAttribArray(0);
        glVertexAttribPointer(0, 2, GL_FLOAT, false, 2 * Float.BYTES, 0);

        // Upload index data
        glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, ibo);
        IntBuffer indexBuffer = BufferUtils.createIntBuffer(indices.length);
        indexBuffer.put(indices).flip();
        glBufferData(GL_ELEMENT_ARRAY_BUFFER, indexBuffer, GL_STATIC_DRAW);

        // Set up projection matrix (Fix to match window coordinates)
        viewProjMatrix.setOrtho(0, myWM.getWindowSize()[0], myWM.getWindowSize()[1], 0, -1, 1);
        glUniformMatrix4fv(vpMatLocation, false, viewProjMatrix.get(myFloatBuffer));

        glPolygonMode(GL_FRONT_AND_BACK, GL_FILL);
        glDrawElements(GL_TRIANGLES, indices.length, GL_UNSIGNED_INT, 0);

        glDisableVertexAttribArray(0);
        glBindBuffer(GL_ARRAY_BUFFER, 0);
        glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, 0);
    }


    private float[] generateTilesVertices(final int rowTiles, final int colTiles) {
        int totalVertices = rowTiles * colTiles * VPT * FPV;
        float[] vertices = new float[totalVertices];
        int index = 0;

        float startX = OFFSET;
        float startY = myWM.getWindowSize()[1] - OFFSET;  // Start from top-left

        for (int row = 0; row < rowTiles; row++) {
            for (int col = 0; col < colTiles; col++) {
                float xmin = startX + col * (SIZE + PADDING);
                float ymin = startY - row * (SIZE + PADDING);

                // Store vertices in correct order
                vertices[index++] = xmin;
                vertices[index++] = ymin;  // Top-left
                vertices[index++] = xmin + SIZE;
                vertices[index++] = ymin;  // Top-right
                vertices[index++] = xmin + SIZE;
                vertices[index++] = ymin - SIZE;  // Bottom-right
                vertices[index++] = xmin;
                vertices[index++] = ymin - SIZE;  // Bottom-left
            }
        }
        return vertices;
    }

    private int[] generateTilesIndices(final int rows, final int cols) {
        int totalIndices = rows * cols * IPV;
        int[] indices = new int[totalIndices];
        int index = 0;

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                int tileNum = row * cols + col;
                int startIV = VPT * tileNum;

                indices[index++] = startIV;
                indices[index++] = startIV + 1;
                indices[index++] = startIV + 2;
                indices[index++] = startIV;
                indices[index++] = startIV + 2;
                indices[index++] = startIV + 3;
            }
        }
        return indices;
    }

}

