package pkgKDUtils;

import org.lwjgl.glfw.GLFWFramebufferSizeCallback;
import org.lwjgl.opengl.GL;

import static org.lwjgl.glfw.GLFW.*;
import static org.lwjgl.opengl.GL11.*;

public class KDWindowManager {
    private static KDWindowManager my_window;
    private static long glfwWindow;
    private static int win_height, win_width, win_x, win_y;

    private KDWindowManager(int width, int height, int orgX, int orgY) {
        this.win_width = width;
        this.win_height = height;
        this.win_x = orgX;
        this.win_y = orgY;
        initGlfwWindow();
    }

    private static GLFWFramebufferSizeCallback resizeWindow = new GLFWFramebufferSizeCallback() {
        @Override
        public void invoke(long window, int width, int height) {
            glViewport(0, 0, width, height);
            win_width = width;
            win_height = height;
        }
    };

    public static KDWindowManager get() {
        if (my_window == null) {
            my_window = new KDWindowManager(1800,1200,50,50);
        }
        return my_window;
    }

    public static KDWindowManager get(int width, int height, int orgX, int orgY) {
        if (my_window == null) {
            my_window = KDWindowManager.get();
        }
        my_window.setWinWidth(width, height);
        my_window.setWindowPosition(orgX, orgY);

        return my_window;
    }

    protected static void setWinWidth(int width, int height) {
        win_width = width;
        win_height = height;
        if(glfwWindow > 0){
            glfwSetWindowSize(glfwWindow, width, height);
            glViewport(0, 0, win_width, win_height);
        }

    }

    public static void setWindowPosition(int orgX, int orgY) {
        win_x = orgX;
        win_y = orgY;
        if (glfwWindow > 0) {
            glfwSetWindowPos(glfwWindow, orgX, orgY);
        }
    }

    public int[] getWindowSize() {
        return new int[]{win_width, win_height};
    }

    public void updateContextToThis() {
        glfwMakeContextCurrent(glfwWindow);
        GL.createCapabilities();
    }

    public void enableResizeWindowCallback() {
        glfwSetFramebufferSizeCallback(glfwWindow, resizeWindow);
    }

    private static void initGlfwWindow() {
        if (!glfwInit()) {
            throw new IllegalStateException("Unable to initialize GLFW");
        }

        glfwWindow = glfwCreateWindow(win_width, win_height, "OpenGL Window", 0, 0);
        if (glfwWindow == 0) {
            throw new RuntimeException("Failed to create the GLFW window");
        }

        glfwSetWindowPos(glfwWindow, win_x, win_y);
        glfwMakeContextCurrent(glfwWindow);
        GL.createCapabilities();
        glfwShowWindow(glfwWindow);
    }

    public void swapBuffers() {
        glfwSwapBuffers(glfwWindow);
    }

    public void destroyGlfwWindow() {
        glfwDestroyWindow(glfwWindow);
        glfwTerminate();
    }

    public boolean isGlfwWindowClosed() {
        return glfwWindowShouldClose(glfwWindow);
    }
}

package pkgKDRenderEngine;

import pkgKDUtils.KDPingPongArray;

import java.util.*;

public class KDGoLArray extends KDPingPongArray {
    public static final int DEAD = 0;
    public static final int LIVE = 1;

    public KDGoLArray(int numRows, int numCols) {
        this(numRows, numCols, (int) (numRows * numCols * 0.2f + 0.5f));
    }

    public KDGoLArray(int numRows, int numCols, int numLiveCells) {
        super(numRows, numCols, 0, 1);
        initRandomLiveCells(numLiveCells);
    }

    public KDGoLArray(String dataFilePath) {
        super(16, 16, 0, 1); // default init
        loadFile(dataFilePath);
        swapLiveAndNext(); // promote loaded content
    }

    private void initRandomLiveCells(int numLiveCells) {
        int total = rows * cols;
        numLiveCells = Math.min(total, Math.max(0, numLiveCells));
        List<Integer> cellStates = new ArrayList<>(Collections.nCopies(numLiveCells, LIVE));
        cellStates.addAll(Collections.nCopies(total - numLiveCells, DEAD));
        Collections.shuffle(cellStates);

        int idx = 0;
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                setCell(r, c, cellStates.get(idx++));
        swapLiveAndNext();
    }

    public void updateToNextGeneration() {
        int[][] current = getArray(); // deep copy of liveArray

        // rules[currentState][neighborCount]
        int[][] rules = new int[2][9];
        for (int i = 0; i < 9; i++) {
            rules[DEAD][i] = (i == 3) ? LIVE : DEAD;
            rules[LIVE][i] = (i == 2 || i == 3) ? LIVE : DEAD;
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int neighbors = countLiveNeighbors(current, r, c);
                int state = current[r][c];
                setCell(r, c, rules[state][neighbors]);
            }
        }

        swapLiveAndNext(); // promote nextArray to live
    }

    private int countLiveNeighbors(int[][] grid, int row, int col) {
        int count = 0;
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                if (dr == 0 && dc == 0) continue;
                int nr = (row + dr + rows) % rows;
                int nc = (col + dc + cols) % cols;
                count += (grid[nr][nc] == LIVE) ? 1 : 0;
            }
        }
        return count;
    }
}

package pkgKDRenderEngine;

import org.joml.Matrix4f;
import org.lwjgl.opengl.GL;
import org.lwjgl.BufferUtils;
import pkgKDUtils.KDGeometryManager;
import pkgKDUtils.KDWindowManager;

import java.nio.FloatBuffer;
import java.nio.IntBuffer;

import static org.lwjgl.glfw.GLFW.glfwPollEvents;
import static org.lwjgl.opengl.GL11.*;
import static org.lwjgl.opengl.GL20.*;

public class KDRenderer {
    private KDWindowManager myWM;
    private Matrix4f viewProjMatrix = new Matrix4f();
    private FloatBuffer myFloatBuffer = BufferUtils.createFloatBuffer(16);
    private int vpMatLocation;
    private int shaderProgram;
    private int OFFSET, PADDING, SIZE;
    private KDGoLArray golArray;
    private KDGeometryManager gm;
    private FloatBuffer vBuffer;
    private int vbo, ibo;

    public KDRenderer(KDWindowManager wm, KDGoLArray golArray, int offset, int size, int padding) {
        this.myWM = wm;
        this.golArray = golArray;
        this.OFFSET = offset;
        this.SIZE = size;
        this.PADDING = padding;
        this.gm = new KDGeometryManager(
                golArray.getArray().length,
                golArray.getArray()[0].length,
                OFFSET, SIZE, PADDING,
                myWM.getWindowSize()
        );
    }

    public void initOpenGL() {
        glClearColor(0.0f, 0.0f, 1.0f, 1.0f);  // blue background
        GL.createCapabilities();
        glEnable(GL_DEPTH_TEST);
        glEnable(GL_CULL_FACE);

        int[] windowSize = myWM.getWindowSize();
        glViewport(0, 0, windowSize[0], windowSize[1]);

        this.shaderProgram = glCreateProgram();

        int vs = glCreateShader(GL_VERTEX_SHADER);
        glShaderSource(vs, """
            #version 330 core
            layout(location = 0) in vec2 position;
            uniform mat4 viewProjMatrix;
            void main() {
                gl_Position = viewProjMatrix * vec4(position, 0.0, 1.0);
            }""");
        glCompileShader(vs);
        checkShaderCompile(vs);
        glAttachShader(shaderProgram, vs);

        int fs = glCreateShader(GL_FRAGMENT_SHADER);
        glShaderSource(fs, """
            #version 330 core
            out vec4 fragColor;
            void main() {
                fragColor = vec4(0.6, 0.7, 0.1, 1.0);
            }""");
        glCompileShader(fs);
        checkShaderCompile(fs);
        glAttachShader(shaderProgram, fs);

        glLinkProgram(shaderProgram);
        glUseProgram(shaderProgram);

        vpMatLocation = glGetUniformLocation(shaderProgram, "viewProjMatrix");
    }

    public void renderObjects() {
        int totalTiles = golArray.getArray().length * golArray.getArray()[0].length;
        float[] vertices = new float[totalTiles * 8];
        int[] indices = gm.generateTileIndices(totalTiles);

        vbo = glGenBuffers();
        ibo = glGenBuffers();

        glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, ibo);
        IntBuffer ib = BufferUtils.createIntBuffer(indices.length);
        ib.put(indices).flip();
        glBufferData(GL_ELEMENT_ARRAY_BUFFER, ib, GL_STATIC_DRAW);

        vBuffer = BufferUtils.createFloatBuffer(vertices.length);

        while (!myWM.isGlfwWindowClosed()) {
            glfwPollEvents();
            glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);

            golArray.updateToNextGeneration();  // evolve the world
            float[] updatedVertices = new float[totalTiles * 8];
            gm.generateTilesVertices(golArray, updatedVertices);

            vBuffer.clear();
            vBuffer.put(updatedVertices).flip();

            glBindBuffer(GL_ARRAY_BUFFER, vbo);
            glBufferData(GL_ARRAY_BUFFER, vBuffer, GL_DYNAMIC_DRAW);

            glEnableVertexAttribArray(0);
            glVertexAttribPointer(0, 2, GL_FLOAT, false, 2 * Float.BYTES, 0);

            viewProjMatrix.setOrtho(0, myWM.getWindowSize()[0], myWM.getWindowSize()[1], 0, -1, 1);
            glUniformMatrix4fv(vpMatLocation, false, viewProjMatrix.get(myFloatBuffer));

            glDrawElements(GL_TRIANGLES, indices.length, GL_UNSIGNED_INT, 0);
            glDisableVertexAttribArray(0);
            glBindBuffer(GL_ARRAY_BUFFER, 0);

            myWM.swapBuffers();
            try {
                Thread.sleep(100); // control speed
            } catch (InterruptedException ignored) {}
        }
    }

    private void checkShaderCompile(int shader) {
        int status = glGetShaderi(shader, GL_COMPILE_STATUS);
        if (status == GL_FALSE) {
            throw new RuntimeException("Shader compile failed: " + glGetShaderInfoLog(shader));
        }
    }
}

package pkgKDUtils;

import pkgKDRenderEngine.KDGoLArray;

public class KDGeometryManager {
    private int rows, cols, offset, size, padding;
    private int winWidth, winHeight;

    public KDGeometryManager(int maxRows, int maxCols, int offset, int size, int padding, int[] winDims) {
        this.rows = maxRows;
        this.cols = maxCols;
        this.offset = offset;
        this.size = size;
        this.padding = padding;
        this.winWidth = winDims[0];
        this.winHeight = winDims[1];
    }

    public float[] generateTilesVertices(int rowTiles, int colTiles) {
        float[] vertices = new float[rowTiles * colTiles * 8];  // 4 corners * 2 coords
        int index = 0;
        for (int row = 0; row < rowTiles; row++) {
            for (int col = 0; col < colTiles; col++) {
                float xmin = offset + col * (size + padding);
                float ymin = winHeight - (offset + row * (size + padding));
                index = fillArrayWithTileVertices(vertices, index, xmin, ymin);
            }
        }
        return vertices;
    }

    public boolean generateTilesVertices(KDGoLArray myGoLA, float[] vertices) {
        int idx = 0;
        int[][] array = myGoLA.getArray();
        for (int row = 0; row < array.length; row++) {
            for (int col = 0; col < array[0].length; col++) {
                if (array[row][col] == KDGoLArray.LIVE) {
                    float xmin = offset + col * (size + padding);
                    float ymin = offset + row * (size + padding);
                    idx = fillArrayWithTileVertices(vertices, idx, xmin, ymin);
                }
            }
        }
        return true;
    }

    public int[] generateTileIndices(int totalTiles) {
        int[] indices = new int[totalTiles * 6]; // 2 triangles per tile
        int idx = 0, v = 0;
        for (int i = 0; i < totalTiles; i++) {
            indices[idx++] = v;
            indices[idx++] = v + 1;
            indices[idx++] = v + 2;
            indices[idx++] = v;
            indices[idx++] = v + 2;
            indices[idx++] = v + 3;
            v += 4;
        }
        return indices;
    }

    private int fillArrayWithTileVertices(float[] vertices, int index, float xmin, float ymin) {
        vertices[index++] = xmin;
        vertices[index++] = ymin;
        vertices[index++] = xmin + size;
        vertices[index++] = ymin;
        vertices[index++] = xmin + size;
        vertices[index++] = ymin - size;
        vertices[index++] = xmin;
        vertices[index++] = ymin - size;
        return index;
    }
}

package pkgKDUtils;

import java.io.*;
import java.util.Random;
import java.util.Scanner;

public class KDPingPongArray {
    protected int[][] liveArray;
    protected int[][] nextArray;
    protected int rows, cols;
    protected final Random random;
    protected int defaultValue;

    public KDPingPongArray(int numRows, int numCols, int randMin, int randMax) {
        this.rows = numRows;
        this.cols = numCols;
        this.random = new Random();

        liveArray = new int[rows][cols];
        nextArray = new int[rows][cols];

        for (int row = 0; row < rows; row++)
            for (int col = 0; col < cols; col++)
                nextArray[row][col] = random.nextInt(randMax - randMin + 1) + randMin;
    }

    public void swapLiveAndNext() {
        int[][] temp = liveArray;
        liveArray = nextArray;
        nextArray = temp;
    }

    public void setCell(int row, int col, int newValue) {
        if (row >= 0 && row < rows && col >= 0 && col < cols)
            nextArray[row][col] = newValue;
    }

    public int[][] getArray() {
        int[][] copy = new int[rows][cols];
        for (int i = 0; i < rows; i++)
            copy[i] = liveArray[i].clone();  // deep copy
        return copy;
    }

    public void loadFile(String dataFileName) {
        try (BufferedReader reader = new BufferedReader(new FileReader(dataFileName))) {
            defaultValue = Integer.parseInt(reader.readLine().trim());
            String[] dims = reader.readLine().trim().split("\\s+");
            rows = Integer.parseInt(dims[0]);
            cols = Integer.parseInt(dims[1]);

            nextArray = new int[rows][cols];
            liveArray = new int[rows][cols];

            String line;
            while ((line = reader.readLine()) != null) {
                String[] parts = line.trim().split("\\s+");
                int r = Integer.parseInt(parts[0]);
                for (int c = 1; c < parts.length; c++) {
                    nextArray[r][c - 1] = Integer.parseInt(parts[c]);
                }
            }

        } catch (IOException e) {
            System.err.println("File loading failed: " + e.getMessage());
        }
    }

    public void printArray() {
        for (int row = 0; row < rows; row++) {
            System.out.print(row + " ");
            for (int col = 0; col < cols; col++) {
                System.out.print(liveArray[row][col] + " ");
            }
            System.out.println();
        }
    }
}

package pkgKDUtils;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class KDPingPongArrayLive extends KDPingPongArray {
    public static final int DEAD = 0;
    public static final int LIVE = 1;

    public KDPingPongArrayLive(int numRows, int numCols, int numLiveCells) {
        super(numRows, numCols, 0, 2);
        int totalCells = numRows * numCols;
        List<Integer> cells = new ArrayList<>(totalCells);

        for (int i = 0; i < numLiveCells; i++) cells.add(LIVE);
        for (int i = numLiveCells; i < totalCells; i++) cells.add(DEAD);
        Collections.shuffle(cells);

        int idx = 0;
        for (int r = 0; r < numRows; r++) {
            for (int c = 0; c < numCols; c++) {
                setCell(r, c, cells.get(idx++));
            }
        }
        swapLiveAndNext();
    }

    public int countLiveDegreeTwoNeighbors(int row, int col) {
        int[][] grid = getArray();
        int count = 0;
        int[][] offsets = {
                {-2, 0}, {2, 0}, {0, -2}, {0, 2},
                {-1, -1}, {-1, 1}, {1, -1}, {1, 1}
        };

        int rows = grid.length;
        int cols = grid[0].length;
        for (int[] offset : offsets) {
            int r = (row + offset[0] + rows) % rows;
            int c = (col + offset[1] + cols) % cols;
            if (grid[r][c] == LIVE) count++;
        }
        return count;
    }
}

package pkgKDUtils;

import org.lwjgl.glfw.GLFWFramebufferSizeCallback;
import org.lwjgl.opengl.GL;

import static org.lwjgl.glfw.GLFW.*;
import static org.lwjgl.opengl.GL11.*;

public class KDWindowManager {
    private static KDWindowManager my_window;
    private static long glfwWindow;
    private static int win_width, win_height, win_x, win_y;

    private KDWindowManager(int width, int height, int orgX, int orgY) {
        win_width = width;
        win_height = height;
        win_x = orgX;
        win_y = orgY;
        initGlfwWindow();
    }

    public static KDWindowManager get() {
        if (my_window == null) {
            my_window = new KDWindowManager(1800, 1200, 50, 50);
        }
        return my_window;
    }

    public static KDWindowManager get(int width, int height, int orgX, int orgY) {
        if (my_window == null) get();
        setWinWidth(width, height);
        setWindowPosition(orgX, orgY);
        return my_window;
    }

    private static void initGlfwWindow() {
        if (!glfwInit()) throw new IllegalStateException("Unable to initialize GLFW");

        glfwWindow = glfwCreateWindow(win_width, win_height, "OpenGL Window", 0, 0);
        if (glfwWindow == 0) throw new RuntimeException("Failed to create GLFW window");

        glfwSetWindowPos(glfwWindow, win_x, win_y);
        glfwMakeContextCurrent(glfwWindow);
        GL.createCapabilities();
        glfwShowWindow(glfwWindow);
    }

    public int[] getWindowSize() {
        return new int[]{win_width, win_height};
    }

    public void updateContextToThis() {
        glfwMakeContextCurrent(glfwWindow);
        GL.createCapabilities();
    }

    public void swapBuffers() {
        glfwSwapBuffers(glfwWindow);
    }

    public void destroyGlfwWindow() {
        glfwDestroyWindow(glfwWindow);
        glfwTerminate();
    }

    public boolean isGlfwWindowClosed() {
        return glfwWindowShouldClose(glfwWindow);
    }

    protected static void setWinWidth(int width, int height) {
        win_width = width;
        win_height = height;
        if (glfwWindow > 0) glfwSetWindowSize(glfwWindow, width, height);
    }

    public static void setWindowPosition(int x, int y) {
        win_x = x;
        win_y = y;
        if (glfwWindow > 0) glfwSetWindowPos(glfwWindow, x, y);
    }
}

